package com.coding.va.selfhelp.presentation.screens.mandate.common

import com.coding.va.selfhelp.domain.model.MandateWindow
import com.coding.va.selfhelp.i18n.MandateStrings
import com.coding.va.selfhelp.i18n.StringPlaceholder
import com.coding.va.selfhelp.i18n.replace
import kotlinx.datetime.DatePeriod
import kotlinx.datetime.LocalDate
import kotlinx.datetime.LocalTime
import kotlinx.datetime.TimeZone
import kotlinx.datetime.atTime
import kotlinx.datetime.minus
import kotlinx.datetime.plus
import kotlinx.datetime.toInstant
import kotlinx.datetime.toLocalDateTime
import kotlin.time.ExperimentalTime
import kotlin.time.Instant

/**
 * Formats the Lands & Peoples submission window in Europe/Amsterdam, matching
 * the timezone the backend uses for the mandate deadline.
 *
 * Named-zone lookup (`TimeZone.of("Europe/Amsterdam")`) is missing on Kotlin/JS,
 * so Amsterdam wall-clock is derived from UTC with the EU DST rule instead.
 */
object MandateHours {

    data class Copy(
        val title: String,
        val description: String,
        val compact: String,
        val lockedDescription: String,
    )

    fun lockedMessage(window: MandateWindow?, strings: MandateStrings): String =
        window?.let { copy(it, strings)?.lockedDescription } ?: strings.lockedDescription

    fun copy(window: MandateWindow, strings: MandateStrings): Copy? = runCatching {
        val opens = window.opensAtEpochSeconds ?: return null
        val closes = window.closesAtEpochSeconds ?: return null
        val months = strings.hoursMonths.split(',')
        val startLong = format(opens, months, includeYear = true)
        val endLong = format(closes, months, includeYear = true)
        val sameYear = yearOf(opens) == yearOf(closes)
        val startShort = format(opens, months, includeYear = !sameYear)
        val endShort = format(closes, months, includeYear = !sameYear)
        Copy(
            title = strings.hoursTitle,
            description = strings.hoursDescription
                .replace(StringPlaceholder.START, startLong)
                .replace(StringPlaceholder.END, endLong),
            compact = strings.hoursCompact
                .replace(StringPlaceholder.START, startShort)
                .replace(StringPlaceholder.END, endShort),
            lockedDescription = strings.lockedDescriptionWithHours
                .replace(StringPlaceholder.START, startLong)
                .replace(StringPlaceholder.END, endLong),
        )
    }.getOrNull()

    @OptIn(ExperimentalTime::class)
    private fun format(epochSeconds: Long, months: List<String>, includeYear: Boolean): String {
        val dt = amsterdamWallClock(epochSeconds)
        val month = months.getOrNull(dt.month.ordinal) ?: dt.month.name.take(3)
        val hh = dt.hour.toString().padStart(2, '0')
        val mm = dt.minute.toString().padStart(2, '0')
        return if (includeYear) "${dt.day} $month ${dt.year}, $hh:$mm"
        else "${dt.day} $month $hh:$mm"
    }

    @OptIn(ExperimentalTime::class)
    private fun yearOf(epochSeconds: Long): Int = amsterdamWallClock(epochSeconds).year

    /**
     * Europe/Amsterdam: UTC+1 in winter, UTC+2 in summer. DST starts on the last
     * Sunday of March at 01:00 UTC and ends on the last Sunday of October at 01:00 UTC.
     */
    @OptIn(ExperimentalTime::class)
    private fun amsterdamWallClock(epochSeconds: Long) =
        Instant.fromEpochSeconds(epochSeconds + amsterdamOffsetSeconds(epochSeconds))
            .toLocalDateTime(TimeZone.UTC)

    @OptIn(ExperimentalTime::class)
    private fun amsterdamOffsetSeconds(epochSeconds: Long): Long {
        val year = Instant.fromEpochSeconds(epochSeconds).toLocalDateTime(TimeZone.UTC).year
        val dstStart = lastSundayOf(year, 3).atTime(LocalTime(1, 0)).toInstant(TimeZone.UTC)
        val dstEnd = lastSundayOf(year, 10).atTime(LocalTime(1, 0)).toInstant(TimeZone.UTC)
        val instant = Instant.fromEpochSeconds(epochSeconds)
        val hours = if (instant >= dstStart && instant < dstEnd) 2 else 1
        return hours * 3600L
    }

    private fun lastSundayOf(year: Int, month: Int): LocalDate {
        val lastDay = LocalDate(year, month, 1).plus(DatePeriod(months = 1)).minus(DatePeriod(days = 1))
        val daysBack = (lastDay.dayOfWeek.ordinal + 1) % 7
        return lastDay.minus(DatePeriod(days = daysBack))
    }
}
