@Composable
fun CraftItemContent(
    display: CraftItemDisplay,
    onEvent: ((CraftItemEvent) -> Unit)? = null
) {
    val numberRegex = remember { Regex("^\\d+\$") }
    val strings = LocalStrings.current
    val numericKeyboard = KeyboardOptions(keyboardType = KeyboardType.Number)

    fun update(form: com.coding.va.selfhelp.domain.model.ItemCraftForm) =
        onEvent?.invoke(CraftItemEvent.UpdateCraftForm(form))

    display.errorBox?.let {
        ErrorBox(
            display = it,
            onConfirmation = { onEvent?.invoke(CraftItemEvent.AddItem) },
            onDismissRequest = { onEvent?.invoke(CraftItemEvent.DismissError) })
    }
    display.verifySheet?.let {
        VerifySheet(
            display = it,
            onConfirm = { onEvent?.invoke(CraftItemEvent.AddItem) },
            onDismiss = { onEvent?.invoke(CraftItemEvent.DismissError) }
        )
    }

    FormShell(
        title = display.title,
        desc = display.description,
        onBack = { onEvent?.invoke(CraftItemEvent.Back) },
        cancelLabel = display.backButton,
        nextLabel = display.nextButton,
        onCancel = { onEvent?.invoke(CraftItemEvent.Back) },
        onNext = { onEvent?.invoke(CraftItemEvent.Verify) },
    ) {
        // ---- Item ----
        FormSection(title = strings.craft.itemSectionTitle) {
            val titleInvalid = display.shouldValidate && !display.form.isTitleValid()
            VortexField(
                label = display.itemTitle.label,
                value = display.form.name,
                hint = display.itemTitle.hint,
                error = if (titleInvalid) strings.a11y.errorRequired else null,
                onValueChange = { update(display.form.copy(name = it)) },
            )
            Spacer(Modifier.height(16.dp))
            val descInvalid = display.shouldValidate && !display.form.isDescriptionValid()
            VortexField(
                label = display.itemDescription.label,
                value = display.form.description,
                hint = display.itemDescription.hint,
                error = if (descInvalid) strings.a11y.errorRequired else null,
                onValueChange = { update(display.form.copy(description = it)) },
            )
            Spacer(Modifier.height(16.dp))
            val capInvalid = display.shouldValidate && !display.form.isImbueCapValid()
            VortexField(
                fieldWidth = 180.dp,
                label = display.itemImbueCap.label,
                value = display.form.imbueCap,
                hint = display.itemImbueCap.hint,
                error = if (capInvalid) strings.a11y.errorRequired else null,
                mono = true,
                keyboardOptions = numericKeyboard,
                                numericOnly = true,
                                placeholder = "0",
                onValueChange = {
                    if (it.isEmpty() || it.matches(numberRegex)) update(display.form.copy(imbueCap = it))
                },
            )
        }

        // ---- Resources & Energy ----
        FormSection(title = strings.craft.resourcesSectionTitle, help = display.resourceDescription) {
            Column(verticalArrangement = Arrangement.spacedBy(16.dp)) {
                display.form.resources.forEach { entry ->
                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .clip(RoundedCornerShape(10.dp))
                            .background(com.coding.va.selfhelp.theme.paperRaised)
                            .border(1.dp, vellumLine, RoundedCornerShape(10.dp))
                            .padding(16.dp),
                        verticalArrangement = Arrangement.spacedBy(16.dp),
                    ) {
                        if (display.form.resources.size > 1) {
                            Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.End) {
                                VortexIconButton(
                                    symbol = "−",
                                    contentDescription = strings.a11y.removeRow,
                                    onClick = { onEvent?.invoke(CraftItemEvent.RemoveResourceRow(entry.key)) },
                                )
                            }
                        }
                        SelectableField(
                            label = display.itemCraftResource.resourceType.label,
                            display = display.itemCraftResource.resourceType,
                            value = entry.value.resourceType?.resourceName,
                            isError = display.shouldValidate && !entry.value.isResourceTypeValid(),
                            onSelected = {
                                update(
                                    display.form.copy(
                                        resources = display.form.resources.toMutableMap().apply {
                                            val resource = CraftingResource.valueOf(it.id)
                                            this[entry.key] = entry.value.copy(
                                                resourceType = resource,
                                                energyAmount = (resource.requiredEnergy * entry.value.resourceAmount.toIntOrZero()).ceil().toString(),
                                            )
                                        }
                                    )
                                )
                            },
                        )
                        VortexField(
                            fieldWidth = 160.dp,
                            label = display.itemCraftResource.resourceAmount.label,
                            value = entry.value.resourceAmount,
                            hint = display.itemCraftResource.resourceAmount.hint,
                            error = if (display.shouldValidate && !entry.value.isResourceAmountValid()) strings.a11y.errorNumbersOnly else null,
                            mono = true,
                            keyboardOptions = numericKeyboard,
                                numericOnly = true,
                                placeholder = "0",
                            onValueChange = {
                                if (it.isEmpty() || it.matches(numberRegex)) {
                                    update(
                                        display.form.copy(
                                            resources = display.form.resources.toMutableMap().apply {
                                                this[entry.key] = entry.value.copy(
                                                    resourceAmount = it,
                                                    energyAmount = ((entry.value.resourceType?.requiredEnergy.orZero()) * it.toIntOrZero()).ceil().toString(),
                                                )
                                            }
                                        )
                                    )
                                }
                            },
                        )
                        SelectableField(
                            label = strings.common.selectEnergyTypeLabel,
                            display = display.itemCraftResource.energyType,
                            value = entry.value.energyType.localizedName(strings),
                            isError = display.shouldValidate && !entry.value.isResourceTypeValid(),
                            onSelected = {
                                update(
                                    display.form.copy(
                                        resources = display.form.resources.toMutableMap().apply {
                                            this[entry.key] = entry.value.copy(energyType = EnergyType.valueOf(it.id))
                                        }
                                    )
                                )
                            },
                        )
                        VortexField(
                            fieldWidth = 160.dp,
                            label = display.itemCraftResource.energyAmount.label,
                            value = entry.value.energyAmount,
                            hint = display.itemCraftResource.energyAmount.hint,
                            error = if (display.shouldValidate && !entry.value.isEnergyAmountValid()) strings.a11y.errorNumbersOnly else null,
                            mono = true,
                            keyboardOptions = numericKeyboard,
                                numericOnly = true,
                                placeholder = "0",
                            onValueChange = {
                                if (it.isEmpty() || it.matches(numberRegex)) {
                                    update(
                                        display.form.copy(
                                            resources = display.form.resources.toMutableMap().apply {
                                                this[entry.key] = entry.value.copy(energyAmount = it)
                                            }
                                        )
                                    )
                                }
                            },
                        )
                        PlinTextField(
                            display = display.itemCraftResource.plin,
                            value = entry.value.plin,
                            isError = display.shouldValidate && !entry.value.isPlinValid(),
                            errorText = if (display.shouldValidate && !entry.value.isPlinValid()) strings.a11y.errorInvalidPlin else null,
                            onValueChange = {
                                update(
                                    display.form.copy(
                                        resources = display.form.resources.toMutableMap().apply {
                                            this[entry.key] = entry.value.copy(plin = it)
                                        }
                                    )
                                )
                            },
                        )
                    }
                }

                VortexButton(
                    text = "＋",
                    onClick = { onEvent?.invoke(CraftItemEvent.AddResourceRow) },
                    variant = VortexButtonVariant.Secondary,
                )

                display.form.getResourcesImbueCap().let {
                    if (it > 0) {
                        Ledger {
                            LedgerLine(label = display.currentlyFromResourcesLabel.trim(), amount = it.toString())
                        }
                    }
                }
            }
        }

        // ---- Special Notes ----
        FormSection(title = strings.common.specialNotesLabel) {
            VortexField(
                value = display.form.notes,
                hint = display.itemNotes.hint,
                singleLine = false,
                minHeight = 96.dp,
                onValueChange = { update(display.form.copy(notes = it)) },
            )
        }

        Spacer(Modifier.height(8.dp))
    }
}
