package com.coding.va.selfhelp.auth

import io.ktor.http.encodeURLQueryComponent

/** Sentinel passed as `login_hint` so the Keycloak theme can hide email/password. */
const val KEYCLOAK_SOCIAL_ONLY_LOGIN_HINT = "va-social-only"

/**
 * Builds the Keycloak Authorization-Code URL for the hosted login page (no `kc_idp_hint`).
 * The user picks Google, Discord, or username/password on auth.the-vortex.nl.
 *
 * When [socialOnly] is true, appends `va_login=social` and `login_hint=va-social-only` so the
 * vortex theme shows social providers only (native app). Verify desk and browsers omit the flag.
 */
fun buildKeycloakAuthUrl(
    issuer: String,
    clientId: String,
    redirectUri: String,
    state: String,
    codeChallenge: String,
    socialOnly: Boolean = false,
): String = buildString {
    append(issuer.trimEnd('/'))
    append("/protocol/openid-connect/auth")
    append("?response_type=code")
    append("&client_id=").append(clientId.encodeURLQueryComponent())
    append("&redirect_uri=").append(redirectUri.encodeURLQueryComponent())
    append("&scope=").append("openid profile email".encodeURLQueryComponent())
    append("&state=").append(state.encodeURLQueryComponent())
    append("&code_challenge=").append(codeChallenge.encodeURLQueryComponent())
    append("&code_challenge_method=S256")
    // Force the account picker even when Keycloak still has an SSO cookie.
    append("&prompt=select_account")
    if (socialOnly) {
        append("&va_login=").append("social".encodeURLQueryComponent())
        append("&login_hint=").append(KEYCLOAK_SOCIAL_ONLY_LOGIN_HINT.encodeURLQueryComponent())
    }
}