package com.coding.va.selfhelp.data.network

import co.touchlab.kermit.Logger
import com.coding.va.selfhelp.data.models.CharacterDetailEntity
import com.coding.va.selfhelp.data.models.CharacterListResponse
import com.coding.va.selfhelp.data.models.CharacterSummaryEntity
import com.coding.va.selfhelp.data.models.ConditionDetailEntity
import com.coding.va.selfhelp.data.models.ItemDetailEntity
import com.coding.va.selfhelp.data.models.PowerDetailEntity
import com.coding.va.selfhelp.domain.respository.AuthRepository
import io.ktor.client.HttpClient
import io.ktor.client.call.body
import io.ktor.client.request.get
import io.ktor.client.statement.bodyAsText
import io.ktor.client.request.header
import io.ktor.http.HttpHeaders
import org.koin.core.annotation.Named
import org.koin.core.annotation.Single
import com.coding.va.selfhelp.data.di.VOID_CLIENT

private val log = Logger.withTag("VoidCharactersApi")

@Single
class VoidCharactersApiImp(
    @Named(VOID_CLIENT) private val client: HttpClient,
    private val authRepository: AuthRepository,
) : VoidCharactersApi {

    private fun authHeader(): String? = authRepository.getAccessToken()?.let { "Bearer $it" }

    override suspend fun getCharacters(plin: Int): List<CharacterSummaryEntity> {
        log.d { "Characters - GET /characters/$plin" }
        val response = client.get("/characters/$plin") {
            authHeader()?.let { header(HttpHeaders.Authorization, it) }
        }
        log.d { "Characters - GET /characters/$plin → status=${response.status}" }
        return response.body<CharacterListResponse>().list
    }

    override suspend fun getCharacterDetail(plin: Int, chin: Int): CharacterDetailEntity {
        log.d { "Characters - GET /characters/$plin/$chin" }
        val response = client.get("/characters/$plin/$chin") {
            authHeader()?.let { header(HttpHeaders.Authorization, it) }
        }
        log.d { "Characters - GET /characters/$plin/$chin → status=${response.status}" }
        return response.body<CharacterDetailEntity>()
    }

    override suspend fun getConditionDetail(coin: Int): ConditionDetailEntity {
        log.d { "Characters - GET /conditions/$coin" }
        val response = client.get("/conditions/$coin") {
            authHeader()?.let { header(HttpHeaders.Authorization, it) }
        }
        return response.body<ConditionDetailEntity>()
    }

    override suspend fun getPowerDetail(poin: Int): PowerDetailEntity {
        log.d { "Characters - GET /powers/$poin" }
        val response = client.get("/powers/$poin") {
            authHeader()?.let { header(HttpHeaders.Authorization, it) }
        }
        return response.body<PowerDetailEntity>()
    }

    override suspend fun getItemDetail(itin: Int): ItemDetailEntity {
        log.d { "Characters - GET /items/$itin" }
        val response = client.get("/items/$itin") {
            authHeader()?.let { header(HttpHeaders.Authorization, it) }
        }
        return response.body<ItemDetailEntity>()
    }

}
