package com.coding.va.selfhelp.di

import com.coding.va.selfhelp.data.AppConfig

/**
 * Eru ecosystem URLs per deployment environment.
 * [baseUrl]   — Keycloak issuer; token endpoint is at `{baseUrl}/protocol/openid-connect/token`.
 * [apiUrl]    — Eru backend (`GET /api/me/profile` for plin resolution).
 * Native app uses `vortex-spa` (PKCE, no secret) with `va_login=social` on the authorize URL
 * to hide email/password. Verify desk and browsers use the same client without that flag.
 */
enum class EruEnvironment(val baseUrl: String, val apiUrl: String) {
    LOCAL(
        baseUrl = "http://localhost:8081/realms/vortex",
        apiUrl = "http://localhost:8080",
    ),
    // No separate test deployment exists; debug builds use the live hosts (same as
    // VOID). LOCAL stays for running the Eru stack on-device.
    TEST(
        baseUrl = "https://auth.the-vortex.nl/realms/vortex",
        apiUrl = "https://eru.the-vortex.nl",
    ),
    PROD(
        baseUrl = "https://auth.the-vortex.nl/realms/vortex",
        apiUrl = "https://eru.the-vortex.nl",
    ),
}

val currentEruEnvironment: EruEnvironment =
    if (AppConfig.isDebug) EruEnvironment.TEST else EruEnvironment.PROD

/** Keycloak client_id used for PKCE token exchange (public client, no secret). */
const val ERU_KEYCLOAK_CLIENT_ID = "vortex-spa"
