private val READING_COLUMN_MAX = 860.dp

@Composable
private fun fieldLabelStyle() = TextStyle(
    fontFamily = BodyFamily(), fontSize = 14.sp, fontWeight = FontWeight.SemiBold, color = ink2
)

@Composable
private fun helpStyle() = TextStyle(fontFamily = BodyFamily(), fontSize = 13.sp, color = ink3)

/* ---------------- TOP BAR ---------------- */

/** Persistent oxblood brand bar. Never repeats the screen title. */
@Composable
fun VortexTopBar(
    modifier: Modifier = Modifier,
    onBack: (() -> Unit)? = null,
    onHome: (() -> Unit)? = null,
    right: @Composable RowScope.() -> Unit = {},
) {
    Column(modifier.fillMaxWidth()) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .background(crest)
                .padding(horizontal = 20.dp, vertical = 14.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(12.dp),
        ) {
            if (onBack != null) {
                TopBarPill(text = "‹ Back", onClick = onBack)
            }
            Image(
                painter = painterResource(Res.drawable.vortex_logo),
                contentDescription = null,
                modifier = Modifier
                    .size(38.dp)
                    .then(if (onHome != null) Modifier.clickable { onHome() } else Modifier),
            )
            Column {
                Text(
                    text = "Vortex Adventures",
                    style = TextStyle(fontFamily = DisplayFamily(), fontWeight = FontWeight.Bold, fontSize = 19.sp),
                    color = pureWhite,
                )
                Text(
                    text = "SELF-HELP STATION",
                    style = TextStyle(fontFamily = BodyFamily(), fontSize = 11.sp, letterSpacing = 1.6.sp),
                    color = giltLight,
                )
            }
            Spacer(Modifier.weight(1f))
            right()
        }
        Box(Modifier.fillMaxWidth().height(3.dp).background(gilt))
    }
}

/** Translucent pill button living in the top bar (back, lang toggle, settings cog, logout). */
@Composable
fun TopBarPill(text: String, onClick: () -> Unit, modifier: Modifier = Modifier) {
    Box(
        modifier = modifier
            .heightIn(min = 44.dp)
            .clip(RoundedCornerShape(VortexRadius.md))
            .background(pureWhite.copy(alpha = 0.10f))
            .border(1.dp, onCrest.copy(alpha = 0.25f), RoundedCornerShape(VortexRadius.md))
            .clickable { onClick() }
            .padding(horizontal = 14.dp),
        contentAlignment = Alignment.Center,
    ) {
        Text(
            text = text,
            style = TextStyle(fontFamily = BodyFamily(), fontWeight = FontWeight.SemiBold, fontSize = 14.sp),
            color = onCrest,
        )
    }
}

/* ---------------- FORM SHELL ---------------- */

@OptIn(ExperimentalLayoutApi::class)
@Composable
fun FormShell(
    title: String,
    onBack: () -> Unit,
    cancelLabel: String,
    nextLabel: String,
    onCancel: () -> Unit,
    onNext: () -> Unit,
    modifier: Modifier = Modifier,
    desc: String? = null,
    nextEnabled: Boolean = true,
    topBarRight: @Composable RowScope.() -> Unit = {},
    content: @Composable ColumnScope.() -> Unit,
) {
    Column(modifier.fillMaxSize().background(paper)) {
        VortexTopBar(onBack = onBack, right = topBarRight)
        // Scrolling body — content capped to a centered reading column.
        KioskScrollColumn(
            modifier = Modifier
                .weight(1f)
                .fillMaxWidth(),
            contentPadding = PaddingValues(horizontal = 24.dp, vertical = 24.dp),
            horizontalAlignment = Alignment.CenterHorizontally,
        ) {
            Column(Modifier.widthIn(max = READING_COLUMN_MAX).fillMaxWidth()) {
                Text(
                    text = title,
                    style = TextStyle(fontFamily = DisplayFamily(), fontWeight = FontWeight.Bold, fontSize = 32.sp, lineHeight = 38.sp),
                    color = ink,
                    modifier = Modifier.semantics { heading() },
                )
                if (desc != null) {
                    Text(
                        text = desc,
                        style = TextStyle(fontFamily = BodyFamily(), fontSize = 17.sp, lineHeight = 27.sp),
                        color = ink2,
                        modifier = Modifier.padding(top = 6.dp),
                    )
                }
                content()
            }
        }
        FormFooter(cancelLabel, nextLabel, onCancel, onNext, nextEnabled)
    }
}

@Composable
fun FormFooter(cancelLabel: String, nextLabel: String, onCancel: () -> Unit, onNext: () -> Unit, nextEnabled: Boolean = true) {
    // Back lives in the top bar — the footer carries only the primary action.
    Column(
        Modifier
            .fillMaxWidth()
            .background(paperRaised),
    ) {
        Box(Modifier.fillMaxWidth().height(1.dp).background(vellumLine))
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .wrapContentWidth(Alignment.CenterHorizontally)
                .widthIn(max = READING_COLUMN_MAX)
                .padding(horizontal = 24.dp, vertical = 16.dp),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            Spacer(Modifier.weight(1f))
            VortexButton(nextLabel, onNext, variant = VortexButtonVariant.Primary, enabled = nextEnabled)
        }
    }
}

/* ---------------- FORM SECTION ---------------- */

@Composable
fun FormSection(
    modifier: Modifier = Modifier,
    title: String? = null,
    help: String? = null,
    content: @Composable ColumnScope.() -> Unit,
) {
    Column(modifier.fillMaxWidth().padding(top = 28.dp)) {
        if (title != null) {
            Text(
                text = title,
                style = TextStyle(fontFamily = DisplayFamily(), fontWeight = FontWeight.SemiBold, fontSize = 20.sp, lineHeight = 24.sp),
                color = ink,
                modifier = Modifier.padding(bottom = 12.dp),
            )
        }
        if (help != null) {
            Text(text = help, style = helpStyle(), modifier = Modifier.padding(bottom = 16.dp))
        }
        content()
    }
}

/* ---------------- FIELD (label-above .ctl control) ---------------- */

@Composable
fun VortexField(
    value: String,
    onValueChange: (String) -> Unit,
    modifier: Modifier = Modifier,
    fieldWidth: Dp? = null,
    expandHelper: Boolean = true,
    label: String? = null,
    placeholder: String? = null,
    hint: String? = null,
    error: String? = null,
    mono: Boolean = false,
    numericOnly: Boolean = false,
    singleLine: Boolean = true,
    minHeight: Dp = 48.dp,
    keyboardOptions: KeyboardOptions = KeyboardOptions.Default,
    enabled: Boolean = true,
) {
    val interaction = remember { MutableInteractionSource() }
    val focused by interaction.collectIsFocusedAsState()
    val isError = error != null
    val shape = RoundedCornerShape(VortexRadius.md)
    val borderColor = when {
        isError -> errorInk
        focused -> crest
        else -> inkFaint
    }
    val textStyle = (if (mono) vortexMono() else TextStyle(fontFamily = BodyFamily(), fontSize = 17.sp))
        .copy(color = ink)

    Column(modifier) {
        if (label != null) {
            Text(text = label, style = fieldLabelStyle(), modifier = Modifier.padding(bottom = 8.dp))
        }
        Box(
            modifier = Modifier
                .then(if (fieldWidth != null) Modifier.width(fieldWidth) else Modifier.fillMaxWidth())
                .heightIn(min = minHeight)
                .clip(shape)
                .background(paperRaised)
                .border(1.5.dp, borderColor, shape)
                .padding(horizontal = 16.dp, vertical = 12.dp),
            contentAlignment = if (singleLine) Alignment.CenterStart else Alignment.TopStart,
        ) {
            BasicTextField(
                value = value,
                onValueChange = { new ->
                    // Amount fields accept digits only; ignore any non-numeric input.
                    if (!numericOnly || new.isEmpty() || new.all { it.isDigit() }) onValueChange(new)
                },
                enabled = enabled,
                singleLine = singleLine,
                textStyle = textStyle,
                cursorBrush = SolidColor(crimson),
                keyboardOptions = keyboardOptions,
                interactionSource = interaction,
                modifier = Modifier.fillMaxWidth(),
                decorationBox = { inner ->
                    if (value.isEmpty() && placeholder != null) {
                        Text(text = placeholder, style = textStyle.copy(color = inkFaint))
                    }
                    inner()
                },
            )
        }
        FieldFooter(error = error, hint = hint, expand = expandHelper, constrainWidth = fieldWidth)
    }
}

/**
 * Helper line(s) under a field. Shows the error AND the hint together (error never hides the hint).
 * When [expand] it fills the section width so the text can run to the right of a narrow field and
 * wraps at the column edge; otherwise (tight rows) it stays within the field's [constrainWidth].
 */
@Composable
fun FieldFooter(error: String?, hint: String?, expand: Boolean, constrainWidth: Dp?) {
    if (error == null && hint.isNullOrBlank()) return
    val widthMod = when {
        expand -> Modifier.fillMaxWidth()
        constrainWidth != null -> Modifier.width(constrainWidth)
        else -> Modifier.fillMaxWidth()
    }
    Column(widthMod.padding(top = 8.dp)) {
        if (error != null) {
            Text(
                text = error,
                style = helpStyle().copy(color = errorInk),
                modifier = Modifier.semantics { liveRegion = LiveRegionMode.Polite },
            )
        }
        if (!hint.isNullOrBlank()) {
            Text(text = hint, style = helpStyle(), modifier = if (error != null) Modifier.padding(top = 2.dp) else Modifier)
        }
    }
}

/** Column headers above a set of supplier rows (PLIN · Amount), aligned to the row's box widths. */
@Composable
fun SupplierHeader(
    plinLabel: String,
    amountLabel: String,
    plinWidth: Dp = 110.dp,
    amountWidth: Dp = 90.dp,
) {
    Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
        Text(text = plinLabel, style = fieldLabelStyle(), modifier = Modifier.width(plinWidth))
        Text(text = amountLabel, style = fieldLabelStyle(), modifier = Modifier.width(amountWidth))
    }
}

/* ---------------- BUTTONS ---------------- */

enum class VortexButtonVariant { Primary, Secondary, Ghost }

@Composable
fun VortexButton(
    text: String,
    onClick: () -> Unit,
    modifier: Modifier = Modifier,
    variant: VortexButtonVariant = VortexButtonVariant.Primary,
    enabled: Boolean = true,
) {
    val shape = RoundedCornerShape(VortexRadius.md)
    val bg = when {
        !enabled -> paperSunken
        variant == VortexButtonVariant.Primary -> crimson
        else -> paper.copy(alpha = 0f)
    }
    val fg = when {
        !enabled -> inkFaint
        variant == VortexButtonVariant.Primary -> pureWhite
        variant == VortexButtonVariant.Secondary -> crimson
        else -> ink2
    }
    val outline = when {
        !enabled -> null
        variant == VortexButtonVariant.Secondary -> crimson
        variant == VortexButtonVariant.Ghost -> inkFaint
        else -> null
    }
    Box(
        modifier = modifier
            .heightIn(min = 48.dp)
            .clip(shape)
            .background(bg)
            .then(if (outline != null) Modifier.border(1.5.dp, outline, shape) else Modifier)
            .clickable(enabled = enabled, role = Role.Button) { onClick() }
            .padding(horizontal = 24.dp),
        contentAlignment = Alignment.Center,
    ) {
        Text(
            text = text,
            style = TextStyle(fontFamily = BodyFamily(), fontWeight = FontWeight.SemiBold, fontSize = 17.sp),
            color = fg,
        )
    }
}

/** Square 44dp +/- control for repeatable rows. */
@Composable
fun VortexIconButton(symbol: String, contentDescription: String, onClick: () -> Unit, modifier: Modifier = Modifier) {
    Box(
        modifier = modifier
            .size(44.dp)
            .clip(RoundedCornerShape(VortexRadius.md))
            .background(paperRaised)
            .border(1.5.dp, inkFaint, RoundedCornerShape(VortexRadius.md))
            .clickable(role = Role.Button) { onClick() }
            .semantics { this.contentDescription = contentDescription },
        contentAlignment = Alignment.Center,
    ) {
        Text(text = symbol, fontSize = 22.sp, color = ink2)
    }
}

/* ---------------- TASK TILE ---------------- */

@Composable
fun TaskTile(
    text: String,
    onClick: () -> Unit,
    modifier: Modifier = Modifier,
    minHeight: Dp = 124.dp,
    subtitle: String? = null,
) {
    val spoken = if (subtitle.isNullOrBlank()) text else "$text. $subtitle"
    Box(
        modifier = modifier
            .heightIn(min = minHeight)
            .clip(RoundedCornerShape(VortexRadius.md))
            .background(crimson)
            .clickable(role = Role.Button) { onClick() }
            .semantics { contentDescription = spoken },
        contentAlignment = Alignment.Center,
    ) {
        // inset gilt keyline — 7dp from the tile edge (design `.task-tile::before`)
        Box(
            Modifier
                .matchParentSize()
                .padding(7.dp)
                .border(1.dp, pureWhite.copy(alpha = 0.22f), RoundedCornerShape(VortexRadius.sm))
        )
        Column(
            modifier = Modifier
                .padding(horizontal = 16.dp, vertical = 14.dp)
                .clearAndSetSemantics { },
            horizontalAlignment = Alignment.CenterHorizontally,
        ) {
            Text(
                text = text,
                style = TextStyle(fontFamily = DisplayFamily(), fontWeight = FontWeight.Bold, fontSize = 22.sp, lineHeight = 26.sp),
                color = pureWhite,
                textAlign = TextAlign.Center,
            )
            if (!subtitle.isNullOrBlank()) {
                Text(
                    text = subtitle,
                    style = TextStyle(fontFamily = BodyFamily(), fontSize = 13.sp, lineHeight = 16.sp),
                    color = pureWhite.copy(alpha = 0.85f),
                    textAlign = TextAlign.Center,
                    modifier = Modifier.padding(top = 4.dp),
                )
            }
        }
    }
}

