/* ---------------- BANNER ---------------- */

enum class BannerKind { Service, Error, Success }

@Composable
fun Banner(kind: BannerKind, text: String, modifier: Modifier = Modifier, title: String? = null) {
    val (bg, outline, fg) = when (kind) {
        BannerKind.Service -> Triple(noticeBg, noticeBorder, ink2)
        BannerKind.Error -> Triple(crimsonTint, crest, crest)
        BannerKind.Success -> Triple(successTint, gilt, ink2)
    }
    Column(
        modifier
            .fillMaxWidth()
            .clip(RoundedCornerShape(VortexRadius.md))
            .background(bg)
            .border(1.dp, outline, RoundedCornerShape(VortexRadius.md))
            .padding(horizontal = 24.dp, vertical = 16.dp)
            .semantics { liveRegion = LiveRegionMode.Polite },
    ) {
        if (title != null) {
            Text(
                text = title,
                style = TextStyle(fontFamily = BodyFamily(), fontWeight = FontWeight.Bold, fontSize = 15.5.sp),
                color = fg,
            )
        }
        Text(text = text, style = TextStyle(fontFamily = BodyFamily(), fontSize = 15.5.sp), color = fg)
    }
}

/* ---------------- ROW CARD ---------------- */

@Composable
fun RowCard(
    modifier: Modifier = Modifier,
    onClick: (() -> Unit)? = null,
    trailing: @Composable (() -> Unit)? = { Text("›", fontSize = 22.sp, color = inkFaint) },
    content: @Composable ColumnScope.() -> Unit,
) {
    Row(
        modifier = modifier
            .fillMaxWidth()
            .clip(RoundedCornerShape(VortexRadius.lg))
            .background(paperRaised)
            .border(1.dp, vellumLine, RoundedCornerShape(VortexRadius.lg))
            .then(if (onClick != null) Modifier.clickable { onClick() } else Modifier)
            .padding(horizontal = 20.dp, vertical = 16.dp),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(16.dp),
    ) {
        Column(Modifier.weight(1f)) { content() }
        trailing?.invoke()
    }
}

/* ---------------- CHOICE SET (pill radios) ---------------- */

@OptIn(ExperimentalLayoutApi::class)
@Composable
fun ChoiceSet(options: List<String>, selectedOption: String?, onSelect: (String) -> Unit, modifier: Modifier = Modifier) {
    FlowRow(modifier, horizontalArrangement = Arrangement.spacedBy(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
        options.forEach { option ->
            val on = option == selectedOption
            Box(
                modifier = Modifier
                    .heightIn(min = 46.dp)
                    .clip(RoundedCornerShape(VortexRadius.md))
                    .background(if (on) crimson else paperRaised)
                    .border(1.5.dp, if (on) crimson else inkFaint, RoundedCornerShape(VortexRadius.md))
                    .clickable(role = Role.RadioButton) { onSelect(option) }
                    .semantics { selected = on }
                    .padding(horizontal = 18.dp, vertical = 11.dp),
                contentAlignment = Alignment.Center,
            ) {
                Text(
                    text = option,
                    style = TextStyle(fontFamily = BodyFamily(), fontWeight = FontWeight.SemiBold, fontSize = 15.sp),
                    color = if (on) pureWhite else ink2,
                )
            }
        }
    }
}
