package com.coding.va.selfhelp.domain.use_cases

import com.coding.va.selfhelp.domain.respository.AuthRepository
import org.koin.core.annotation.Factory

/**
 * Attempts a silent token refresh using the stored Keycloak refresh token.
 * On success the new token pair is persisted; on failure the caller should
 * treat the session as expired and navigate to the login screen.
 */
@Factory
class RefreshEruTokenUseCase(private val repository: AuthRepository) {

    suspend operator fun invoke(): Result<Unit> {
        val refreshToken = repository.getRefreshToken()
            ?: return Result.failure(IllegalStateException("No refresh token stored"))
        return repository.refreshTokens(refreshToken)
            .map { (access, refresh) ->
                repository.storeTokens(access, refresh)
            }
    }
}
