package com.coding.va.selfhelp.di

import com.coding.va.selfhelp.data.AppConfig

/**
 * Represents the available backend environments for the VOID API.
 *
 */
enum class VoidEnvironment(val baseUrl: String) {
    LOCAL("http://192.168.2.20:8765"),
    // VOID now lives at a single host on the shared vortex stack for both
    // debug and release builds; LOCAL stays for running VOID on-device.
    TEST("https://void-api.the-vortex.nl"),
    PROD("https://void-api.the-vortex.nl"),
}

val currentVoidEnvironment: VoidEnvironment =
    if (AppConfig.isDebug) VoidEnvironment.TEST else VoidEnvironment.PROD
