package com.coding.va.selfhelp.presentation.screens.mainscreen.destinations

import androidx.navigation.NavOptions
import com.coding.va.selfhelp.presentation.screens.success.model.SuccessData
import kotlinx.serialization.Serializable

@Serializable
sealed class MainDestinations(
    open val route: String,
) {
    @Serializable
    data object Landing : MainDestinations("Landing")

    @Serializable
    data class CraftItem(
        val prefillDescription: String = "",
        val prefillImbueCap: String = "",
        val prefillEnergy: String = "",
        val prefillResources: String = "",
        val prefillNotes: String = "",
    ) : MainDestinations("CraftItem")

    @Serializable
    data class Success(val data: SuccessData) : MainDestinations("Success")

    @Serializable
    data class Imbue(
        val isPerson: Boolean,
        val prefillEnergy: String = "",
        val prefillImbueResources: String = "",
        val prefillNotes: String = "",
    ) : MainDestinations("Imbue")

    @Serializable
    data class RechargeItem(
        val prefillItin: String = "",
        val prefillEnergyAmount: String = "",
        val prefillEnergyType: String = "",
        val prefillPlin: String = "",
        val prefillChin: String = "",
    ) : MainDestinations("RechargeItem")

    @Serializable
    data object MundaneItem : MainDestinations("MundaneItem")

    @Serializable
    data object MandateSelect : MainDestinations("MandateSelect")

    @Serializable
    data object LandMandate : MainDestinations("LandMandate")

    @Serializable
    data object PeopleMandate : MainDestinations("PeopleMandate")

    @Serializable
    data object MilitaryMandate : MainDestinations("MilitaryMandate")

    @Serializable
    data class MandateSubmitted(
        val formTypeLabel: String,
        val subject: String,
        val cardCode: String,
    ) : MainDestinations("MandateSubmitted")

    @Serializable
    data object History : MainDestinations("History")

    @Serializable
    data object Login : MainDestinations("Login")

    @Serializable
    data object CharacterSelect : MainDestinations("CharacterSelect")

    @Serializable
    data object CharacterDetail : MainDestinations("CharacterDetail")
}