@Composable
fun ImbueContent(
    display: ImbueDisplay,
    onEvent: ((ImbueEvent) -> Unit)? = null
) {
    val numberRegex = remember { Regex("^\\d+\$") }
    val strings = LocalStrings.current
    val numericKeyboard = KeyboardOptions(keyboardType = KeyboardType.Number)
    val helpStyle = TextStyle(fontFamily = BodyFamily(), fontSize = 14.sp, color = ink3)

    fun update(form: com.coding.va.selfhelp.domain.model.ImbueForm) =
        onEvent?.invoke(ImbueEvent.UpdateImbueForm(form))

    display.errorBox?.let {
        ErrorBox(display = it, onConfirmation = { }, onDismissRequest = { onEvent?.invoke(ImbueEvent.DismissError) })
    }
    display.verifySheet?.let {
        VerifySheet(display = it, onConfirm = { onEvent?.invoke(ImbueEvent.AddImbue) }, onDismiss = { onEvent?.invoke(ImbueEvent.DismissError) })
    }

    FormShell(
        title = display.title,
        desc = display.description,
        onBack = { onEvent?.invoke(ImbueEvent.Back) },
        cancelLabel = display.backButton,
        nextLabel = display.validate,
        onCancel = { onEvent?.invoke(ImbueEvent.Back) },
        onNext = { onEvent?.invoke(ImbueEvent.Verify) },
    ) {
        // ---- Target ----
        FormSection(title = strings.common.sectionTarget) {
            val targetInvalid = display.shouldValidate && !display.form.isTargetValid()
            if (display.isPerson) {
                PlinTextField(
                    display = display.imbueTarget,
                    isError = targetInvalid,
                    errorText = if (targetInvalid) strings.a11y.errorInvalidPlin else null,
                    value = display.form.targetPlin ?: Pair("", ""),
                    onValueChange = { update(display.form.copy(targetPlin = it)) },
                )
            } else {
                VortexField(
                    label = display.imbueTarget.plinLabel,
                    value = display.form.targetItin.orEmpty(),
                    hint = display.imbueTarget.plinHint,
                    error = if (targetInvalid) strings.a11y.errorRequired else null,
                    mono = true,
                    onValueChange = { update(display.form.copy(targetItin = it)) },
                )
            }
        }

        // ---- The Imbue (one bordered group per effect) ----
        FormSection(title = strings.common.sectionTheImbue, help = display.imbueDescription) {
            Column(verticalArrangement = Arrangement.spacedBy(16.dp)) {
                display.form.imbueResources.forEach { entry ->
                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .clip(RoundedCornerShape(10.dp))
                            .background(paperRaised)
                            .border(1.dp, vellumLine, RoundedCornerShape(10.dp))
                            .padding(16.dp),
                        verticalArrangement = Arrangement.spacedBy(16.dp),
                    ) {
                        Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween, verticalAlignment = Alignment.CenterVertically) {
                            Text(
                                text = display.imbueEffectNumber + entry.key,
                                style = TextStyle(fontFamily = DisplayFamily(), fontWeight = FontWeight.SemiBold, fontSize = 16.sp),
                            )
                            if (display.form.imbueResources.size > 1) {
                                VortexIconButton(
                                    symbol = "−",
                                    contentDescription = strings.a11y.removeRow,
                                    onClick = { onEvent?.invoke(ImbueEvent.RemoveImbueResource(entry.key)) },
                                )
                            }
                        }

                        SelectableField(
                            label = display.imbueResource.imbueType.label,
                            display = display.imbueResource.imbueType,
                            value = entry.value.imbueType?.displayName,
                            isError = display.shouldValidate && !entry.value.isResourceTypeValid(),
                            onSelected = { result ->
                                update(
                                    display.form.copy(
                                        imbueResources = display.form.imbueResources.toMutableMap().apply {
                                            val resource = ImbueTypes.getAllImbueTypes(display.isPerson, strings).firstOrNull { it.id == result.id }
                                            this[entry.key] = entry.value.copy(
                                                imbueType = resource,
                                                imbueOption = null,
                                                amount = if (resource?.multiplePossible == false) "1" else this[entry.key]?.amount.orEmpty(),
                                                skillSpell = if (resource?.hasOpenPowerField == true) entry.value.skillSpell else "",
                                            )
                                        }
                                    )
                                )
                            },
                        )

                        if (entry.value.imbueType?.options?.isEmpty() != true) {
                            SelectableField(
                                label = display.imbueResource.imbueOption.label,
                                display = display.imbueResource.imbueOption.copy(content = entry.value.imbueType?.options?.map {
                                    SelectableFieldContent(displayValue = it.displayName, id = it.name)
                                }.orEmpty()),
                                value = entry.value.imbueOption?.displayName,
                                isError = display.shouldValidate && !entry.value.isImbueOptionValid(),
                                onSelected = { result ->
                                    update(
                                        display.form.copy(
                                            imbueResources = display.form.imbueResources.toMutableMap().apply {
                                                val option = ImbueOption.valueOf(result.id)
                                                this[entry.key] = entry.value.copy(
                                                    imbueOption = option,
                                                    energyAmount = option?.let { (option.getEnergy(entry.value.imbueType) * entry.value.amount.toIntOrZero()).toString() }.orEmpty(),
                                                )
                                            }
                                        )
                                    )
                                },
                            )
                        }

                        VortexField(
                            fieldWidth = 160.dp,
                            label = display.imbueResource.amount.label,
                            value = display.form.imbueResources[entry.key]?.amount.orEmpty(),
                            hint = display.imbueResource.amount.hint,
                            error = if (display.shouldValidate && !entry.value.isResourceAmountValid()) strings.a11y.errorNumbersOnly else null,
                            mono = true,
                            enabled = entry.value.imbueType?.multiplePossible ?: true,
                            keyboardOptions = numericKeyboard,
                                numericOnly = true,
                                placeholder = "0",
                            onValueChange = { result ->
                                if (result.isEmpty() || result.matches(numberRegex)) {
                                    update(
                                        display.form.copy(
                                            imbueResources = display.form.imbueResources.toMutableMap().apply {
                                                val option = entry.value.imbueOption
                                                this[entry.key] = entry.value.copy(
                                                    amount = result,
                                                    energyAmount = option?.let { (option.getEnergy(entry.value.imbueType) * result.toIntOrZero()).toString() }.orEmpty(),
                                                )
                                            }
                                        )
                                    )
                                }
                            },
                        )

                        if (entry.value.imbueType?.hasOpenPowerField == true) {
                            val isCustom = entry.value.imbueType?.id == ImbueTypes.CUSTOM
                            val fieldDisplay = if (isCustom) display.imbueResource.custom else display.imbueResource.skillSpell
                            VortexField(
                                label = fieldDisplay.label,
                                value = entry.value.skillSpell,
                                hint = fieldDisplay.hint,
                                error = if (display.shouldValidate && !entry.value.isSpellSkillValid()) strings.a11y.errorRequired else null,
                                onValueChange = {
                                    update(
                                        display.form.copy(
                                            imbueResources = display.form.imbueResources.toMutableMap().apply {
                                                this[entry.key] = entry.value.copy(skillSpell = it)
                                            }
                                        )
                                    )
                                },
                            )
                        }

                        VortexField(
                            fieldWidth = 160.dp,
                            label = display.imbueResource.energyAmount.label,
                            value = entry.value.energyAmount,
                            hint = display.imbueResource.energyAmount.hint,
                            mono = true,
                            enabled = entry.value.imbueType?.canModifyEnergy ?: display.imbueResource.energyAmount.enabled,
                            keyboardOptions = numericKeyboard,
                                numericOnly = true,
                                placeholder = "0",
                            onValueChange = {
                                update(
                                    display.form.copy(
                                        imbueResources = display.form.imbueResources.toMutableMap().apply {
                                            this[entry.key] = entry.value.copy(energyAmount = it)
                                        }
                                    )
                                )
                            },
                        )
                        PlinTextField(
                            display = display.imbueResource.plin,
                            label = strings.imbue.imbuerPlinLabel,
                            value = entry.value.headImbuerPlin,
                            isError = display.shouldValidate && !entry.value.isPlinValid(),
                            errorText = if (display.shouldValidate && !entry.value.isPlinValid()) strings.a11y.errorInvalidPlin else null,
                            onValueChange = {
                                update(
                                    display.form.copy(
                                        imbueResources = display.form.imbueResources.toMutableMap().apply {
                                            this[entry.key] = entry.value.copy(
                                                headImbuerPlin = it,
                                                energySuppliers = entry.value.energySuppliers.toMutableMap().apply {
                                                    this[1] = this[1]?.copy(plin = it) ?: ImbueEnergySupplier()
                                                },
                                            )
                                        }
                                    )
                                )
                            },
                        )

                        Ledger {
                            LedgerLine(
                                label = display.imbueResource.currentEnergyLabel.trim(),
                                amount = entry.value.energySuppliers.values.mapNotNull { it.amount.toIntOrNull() }.sum().toString(),
                            )
                        }
                        SelectableField(
                            label = strings.common.selectEnergyTypeLabel,
                            display = display.imbueResource.energyType,
                            value = entry.value.energyType.localizedName(strings),
                            onSelected = {
                                update(
                                    display.form.copy(
                                        imbueResources = display.form.imbueResources.toMutableMap().apply {
                                            this[entry.key] = entry.value.copy(energyType = EnergyType.valueOf(it.id))
                                        }
                                    )
                                )
                            },
                        )

                        // energy suppliers
                        Text(
                            text = display.imbueResource.energySupplierDescription.replace(ENERGY_TYPE, entry.value.energyType.localizedName(strings)),
                            style = helpStyle,
                        )
                        Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {
                            SupplierHeader(plinLabel = strings.common.supplierPlinLabel, amountLabel = strings.common.amountLabel)
                            entry.value.energySuppliers.forEach { supplier ->
                                Row(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalAlignment = Alignment.Top) {
                                    PlinTextField(
                                        display = display.imbueResource.energySupplierPlin,
                            expandHelper = false,
                                        value = supplier.value.plin,
                                        isError = display.shouldValidate && !supplier.value.plin.first.isNotBlank(),
                                        onValueChange = {
                                            update(
                                                display.form.copy(
                                                    imbueResources = display.form.imbueResources.toMutableMap().apply {
                                                        this[entry.key] = entry.value.copy(
                                                            energySuppliers = entry.value.energySuppliers.toMutableMap().apply {
                                                                this[supplier.key] = supplier.value.copy(plin = it)
                                                            }
                                                        )
                                                    }
                                                )
                                            )
                                        },
                                    )
                                    VortexField(
                                        fieldWidth = 90.dp, expandHelper = false,
                                        value = supplier.value.amount,
                                        error = if (display.shouldValidate && !entry.value.isEnergyAmountValid()) strings.a11y.errorNumbersOnly else null,
                                        mono = true,
                                        enabled = display.imbueResource.energySupplierAmount.enabled,
                                        keyboardOptions = numericKeyboard,
                                numericOnly = true,
                                placeholder = "0",
                                        onValueChange = {
                                            update(
                                                display.form.copy(
                                                    imbueResources = display.form.imbueResources.toMutableMap().apply {
                                                        this[entry.key] = entry.value.copy(
                                                            energySuppliers = entry.value.energySuppliers.toMutableMap().apply {
                                                                this[supplier.key] = supplier.value.copy(amount = it)
                                                            }
                                                        )
                                                    }
                                                )
                                            )
                                        },
                                    )
                                    if (entry.value.energySuppliers.size > 1) {
                                        VortexIconButton(
                                            symbol = "−",
                                            contentDescription = strings.a11y.removeRow,
                                            onClick = { onEvent?.invoke(ImbueEvent.RemovePowerSupplier(entry.key, supplier.key)) },
                                        )
                                    }
                                }
                            }
                            VortexButton(
                                text = "＋ " + strings.common.addSupplierLabel,
                                onClick = { onEvent?.invoke(ImbueEvent.AddPowerSupplier(entry.key)) },
                                variant = VortexButtonVariant.Secondary,
                            )
                        }
                    }
                }

                VortexButton(
                    text = "＋",
                    onClick = { onEvent?.invoke(ImbueEvent.AddImbueResource) },
                    variant = VortexButtonVariant.Secondary,
                )
            }
        }

        // ---- Special Notes ----
        FormSection(title = display.imbueNotes.label) {
            VortexField(
                value = display.form.notes,
                hint = display.imbueNotes.hint,
                singleLine = false,
                minHeight = 96.dp,
                onValueChange = { update(display.form.copy(notes = it)) },
            )
        }

        Spacer(Modifier.height(8.dp))
    }
}
