/**
 * Inline choice pills (design `.choice` set). Each option is selectable as a unit; the selected
 * one fills crimson. Keeps the generic `Pair<T, label>` API so callers don't change.
 */
@OptIn(ExperimentalLayoutApi::class)
@Composable
fun <T> MandateRadioRow(
    options: List<Pair<T, String>>,
    selected: T?,
    onSelect: (T) -> Unit,
    modifier: Modifier = Modifier,
) {
    FlowRow(
        modifier = modifier,
        horizontalArrangement = Arrangement.spacedBy(8.dp),
        verticalArrangement = Arrangement.spacedBy(8.dp),
    ) {
        options.forEach { (value, label) ->
            val on = selected == value
            Box(
                modifier = Modifier
                    .heightIn(min = 46.dp)
                    .clip(RoundedCornerShape(5.dp))
                    .background(if (on) crimson else paperRaised)
                    .border(1.5.dp, if (on) crimson else inkFaint, RoundedCornerShape(5.dp))
                    .selectable(selected = on, onClick = { onSelect(value) }, role = Role.RadioButton)
                    .padding(horizontal = 18.dp, vertical = 11.dp),
                contentAlignment = Alignment.Center,
            ) {
                Text(
                    text = label,
                    style = TextStyle(fontFamily = BodyFamily(), fontWeight = FontWeight.SemiBold, fontSize = 15.sp),
                    color = if (on) pureWhite else ink2,
                )
            }
        }
    }
}
