package com.coding.va.selfhelp.presentation.components

import androidx.compose.ui.Modifier
import com.coding.va.selfhelp.di.getPlatform
import com.coding.va.selfhelp.utils.TYPE


fun Modifier.onlyIf(
    condition: Boolean,
    modifier: Modifier.() -> Modifier
): Modifier = if (condition) this.then(modifier()) else this


fun Modifier.onlyDesktop(
    modifier: Modifier.() -> Modifier
): Modifier = if (getPlatform() == TYPE.DESKTOP) this.then(modifier()) else this

fun Modifier.onlyMobile(
    modifier: Modifier.() -> Modifier
): Modifier = if (getPlatform().isMobile) this.then(modifier()) else this