package com.coding.va.selfhelp.presentation.screens.landing.model

import com.coding.va.selfhelp.presentation.components.errorbox.model.ErrorBoxDisplay
import com.coding.va.selfhelp.presentation.methods.LoadingButtonDisplay
import com.coding.va.selfhelp.presentation.screens.mainscreen.model.TaskType
import com.coding.va.selfhelp.presentation.screens.model.FieldDisplay

data class LandingScreenDisplay(
    val title: String,
    val description: String,
    val serviceMessage: String?,
    val tasks: List<LandingScreenTask>,
    val menuDisplay: MenuDisplay,
    val printDescription: String?,
    val printField: FieldDisplay?,
    val cardCode: String,
    val attemptPrintButton: LoadingButtonDisplay?,
    val errorBox: ErrorBoxDisplay?,
    val feedbackButton: String?,
    val feedbackUrl: String?,
    /** Label showing the language the button will switch TO, e.g. "NL" or "EN". */
    val languageToggleLabel: String,
    /** Navigate-to-login button label, shown on mobile only. Null on desktop/web. */
    val loginButton: String?,
    /** Button to navigate to the active character detail. Null when not logged in or no character selected. */
    val myCharacterButton: String?,
)

data class LandingScreenTask(
    val title: String,
    val taskType: TaskType,
    val action: LandingScreenEvent,
    val subtitle: String? = null,
)

sealed class MenuDisplay(
    open val header: String,
) {
    data class Locked(
        override val header: String,
        val passwordLabel: String,
        val password: String,
    ) : MenuDisplay(header)

    data class UnLocked(
        override val header: String,
        val printerIpLabel: String,
        val printerIp: String,
        val printerEnabled: Boolean,
        val printerEnabledLabel: String,
        val printerCodeEnabled: Boolean,
        val printerCodeEnabledLabel: String,
        val printerMode: String,
        val printerModeLabel: String,
        val printerModeUsbLabel: String,
        val printerModeNetworkLabel: String,
        val deviceIpLabel: String,
        val deviceIp: String,
        val save: String,
        val lock: String,
    ) : MenuDisplay(header)
}



