package com.coding.va.selfhelp.presentation.screens.character.select

import com.coding.va.selfhelp.domain.model.CharacterSummary
import com.coding.va.selfhelp.i18n.AppStrings
import com.coding.va.selfhelp.presentation.screens.character.select.model.CharacterSelectItemDisplay
import com.coding.va.selfhelp.presentation.screens.character.select.model.CharacterSelectScreenDisplay

object CharacterSelectDisplayProvider {

    fun loading(): CharacterSelectScreenDisplay = CharacterSelectScreenDisplay.Loading

    fun display(
        strings: AppStrings,
        characters: List<CharacterSummary>,
    ): CharacterSelectScreenDisplay = CharacterSelectScreenDisplay.Display(
        title = strings.character.selectTitle,
        subtitle = strings.character.selectSubtitle,
        characters = characters.map {
            CharacterSelectItemDisplay(
                plin = it.plin,
                chin = it.chin,
                name = it.name,
                statusLabel = it.status,
            )
        },
        backButton = strings.character.backButton,
    )

    fun error(strings: AppStrings): CharacterSelectScreenDisplay =
        CharacterSelectScreenDisplay.Error(
            message = strings.character.selectErrorMessage,
            retryButton = strings.character.retryButton,
            backButton = strings.character.backButton,
        )

    /** Stub [Display] for Compose previews. */
    fun previewDisplay(): CharacterSelectScreenDisplay = CharacterSelectScreenDisplay.Display(
        title = "Select Your Character",
        subtitle = "Choose which character you want to play",
        characters = listOf(
            CharacterSelectItemDisplay(6710, 2, "Halion von Stratmacht", "active"),
            CharacterSelectItemDisplay(6710, 1, "Deitos", "active"),
        ),
        backButton = "Back",
    )
}