package com.coding.va.selfhelp

import androidx.compose.foundation.background
import androidx.compose.foundation.layout.Box
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.foundation.layout.safeDrawingPadding
import androidx.compose.material.MaterialTheme
import androidx.compose.material.lightColors
import androidx.compose.runtime.Composable
import androidx.compose.runtime.collectAsState
import androidx.compose.runtime.getValue
import androidx.compose.ui.Modifier
import androidx.navigation.NavController
import com.coding.va.selfhelp.i18n.LanguageRepository
import com.coding.va.selfhelp.i18n.LocalStrings
import com.coding.va.selfhelp.presentation.a11y.LocalReduceMotion
import com.coding.va.selfhelp.presentation.a11y.rememberReduceMotion
import com.coding.va.selfhelp.presentation.screens.mainscreen.MainScreen
import com.coding.va.selfhelp.presentation.screens.mainscreen.MainViewModel
import com.coding.va.selfhelp.theme.VortexTheme
import com.coding.va.selfhelp.theme.VortexTypography
import com.coding.va.selfhelp.theme.VortexTypographyM2
import com.coding.va.selfhelp.theme.crimson
import com.coding.va.selfhelp.theme.errorInk
import com.coding.va.selfhelp.theme.ink
import com.coding.va.selfhelp.theme.paper
import com.coding.va.selfhelp.theme.paperRaised
import androidx.compose.runtime.CompositionLocalProvider
import androidx.compose.material3.MaterialTheme as Material3Theme
import androidx.compose.material3.lightColorScheme
import org.koin.compose.koinInject

@Composable
fun App(mainViewModel: MainViewModel, onNavHostReady: suspend (NavController) -> Unit = {}) {
    val languageRepository: LanguageRepository = koinInject()
    val strings by languageRepository.stringsFlow().collectAsState()
    val reduceMotion by rememberReduceMotion()

    // Two themes nested: the app mixes Material 2 (caption / colors consumers like SelectableField,
    // PlinTextField) and Material 3 (TextLayout reads MaterialTheme.typography). Supply parchment
    // colors + Vortex fonts to both.
    MaterialTheme(
        colors = lightColors(
            primary = crimson,
            background = paper,
            surface = paperRaised,
            error = errorInk,
            onBackground = ink,
            onSurface = ink,
        ),
        typography = VortexTypographyM2(),
    ) {
        Material3Theme(
            colorScheme = lightColorScheme(
                primary = crimson,
                background = paper,
                surface = paperRaised,
                error = errorInk,
                onBackground = ink,
                onSurface = ink,
            ),
            typography = VortexTypography(),
        ) {
            CompositionLocalProvider(
                LocalStrings provides strings,
                LocalReduceMotion provides reduceMotion,
            ) {
                // Fill the whole screen (including behind system bars) with parchment, then pad the
                // content into the safe drawing area. safeDrawingPadding() is a no-op on desktop /
                // iOS / web so this is safe in commonMain.
                Box(
                    modifier = Modifier
                        .fillMaxSize()
                        .background(VortexTheme.background)
                        .safeDrawingPadding()
                ) {
                    MainScreen(mainViewModel, onNavHostReady)
                }
            }
        }
    }
}
