package com.coding.va.selfhelp.domain.model

data class ImbueForm(
    val isPerson: Boolean,
    val targetItin: String?,
    val targetPlin: Pair<String, String>?,
    val notes: String,
    val imbueResources: Map<Int, ImbueResourceForm>
)

data class ImbueResourceForm(
    val amount: String = "1",
    val imbueType: ImbueType? = null,
    val imbueOption: ImbueOption? = null,
    val skillSpell: String = "",
    val energyAmount: String = "",
    val energyType: EnergyType = EnergyType.SPIRITUAL_MANA,
    val headImbuerPlin: Pair<String, String> = Pair("", ""),
    val energySuppliers: Map<Int, ImbueEnergySupplier> = mapOf(1 to ImbueEnergySupplier()),
)

data class ImbueEnergySupplier(
    val amount: String = "",
    val plin: Pair<String, String> = Pair("", ""),
)
