package com.coding.va.selfhelp.presentation.screens.landing



import com.coding.va.selfhelp.di.getPlatform
import com.coding.va.selfhelp.i18n.AppStrings
import com.coding.va.selfhelp.presentation.components.errorbox.model.ErrorBoxDisplay
import com.coding.va.selfhelp.presentation.methods.LoadingButtonDisplay
import com.coding.va.selfhelp.presentation.screens.landing.model.LandingScreenEvent
import com.coding.va.selfhelp.presentation.screens.landing.model.LandingScreenDisplay
import com.coding.va.selfhelp.presentation.screens.landing.model.LandingScreenTask
import com.coding.va.selfhelp.presentation.screens.landing.model.MenuDisplay
import com.coding.va.selfhelp.presentation.screens.mainscreen.model.TaskType
import com.coding.va.selfhelp.presentation.screens.model.FieldDisplay

object LandingScreenDisplayProvider {

    fun mapLandingDisplay(
        printFieldEnabled: Boolean,
        canMakeCreation: Boolean,
        strings: AppStrings,
        languageToggleLabel: String = "NL",
        isLoggedIn: Boolean = false,
        hasActiveCharacter: Boolean = false,
        mandateHours: String? = null,
    ) = LandingScreenDisplay(
        title = strings.landing.title,
        description = strings.landing.description,
        serviceMessage = if (!canMakeCreation) strings.landing.serviceMessage else null,
        tasks = buildList {
            add(LandingScreenTask(
                title = strings.landing.craftItemTask,
                taskType = TaskType.CreateItem,
                action = LandingScreenEvent.Navigate(TaskType.CreateItem)
            ))
            add(LandingScreenTask(
                title = strings.landing.imbueItemTask,
                taskType = TaskType.ImbueItem,
                action = LandingScreenEvent.Navigate(TaskType.ImbueItem)
            ))
            add(LandingScreenTask(
                title = strings.landing.imbuePersonTask,
                taskType = TaskType.ImbuePerson,
                action = LandingScreenEvent.Navigate(TaskType.ImbuePerson)
            ))
            add(LandingScreenTask(
                title = strings.landing.rechargeItemTask,
                taskType = TaskType.RechargeItem,
                action = LandingScreenEvent.Navigate(TaskType.RechargeItem)
            ))
            add(LandingScreenTask(
                title = strings.landing.mundaneItemsTask,
                taskType = TaskType.MundaneItem,
                action = LandingScreenEvent.Navigate(TaskType.MundaneItem)
            ))
            add(LandingScreenTask(
                title = strings.landing.mandateTask,
                taskType = TaskType.Mandate,
                action = LandingScreenEvent.Navigate(TaskType.Mandate),
                subtitle = mandateHours,
            ))
            if (getPlatform().isMobile) {
                add(LandingScreenTask(
                    title = strings.landing.viewHistoryTask,
                    taskType = TaskType.ViewHistory,
                    action = LandingScreenEvent.Navigate(TaskType.ViewHistory)
                ))
            }
        },
        menuDisplay = provideMenu(strings),
        printField = if (printFieldEnabled) {
            FieldDisplay(strings.landing.printFieldLabel, strings.landing.printFieldHint)
        } else null,
        cardCode = "",
        printDescription = strings.landing.printDescription,
        attemptPrintButton = LoadingButtonDisplay(strings.landing.printButton, false, true),
        errorBox = null,
        feedbackButton = if (!getPlatform().isMobile) null else strings.landing.feedbackButton,
        feedbackUrl = if (!getPlatform().isMobile) null else "https://docs.google.com/forms/d/e/1FAIpQLSfq7bbv_qKL3PceLataFaeu687Uv9g2hEoZAHUQgOCnh5WivA/viewform?usp=dialog",
        languageToggleLabel = languageToggleLabel,
        loginButton = if (getPlatform().supportsOAuthLogin && !isLoggedIn) strings.login.sectionTitle else null,
        myCharacterButton = if (isLoggedIn && hasActiveCharacter) strings.character.myCharacterButton else null,
    )

    fun provideMenu(strings: AppStrings) = MenuDisplay.Locked(
        header = strings.landing.menuHeader,
        passwordLabel = strings.landing.menuPasswordLabel,
        password = ""
    )

    fun providePrintError(strings: AppStrings) = ErrorBoxDisplay(
        title = strings.landing.printErrorTitle,
        description = strings.landing.printErrorDescription,
        retryButton = "Ok",
        acceptButton = null,
    )

    fun provideAlreadyPrintedError(strings: AppStrings) = ErrorBoxDisplay(
        title = strings.landing.alreadyPrintedTitle,
        description = strings.landing.alreadyPrintedDescription,
        retryButton = "Ok",
        acceptButton = null,
    )
}
