package com.coding.va.selfhelp.presentation.screens.character.detail.model

sealed class CharacterDetailScreenDisplay {
    data object Loading : CharacterDetailScreenDisplay()

    data class Display(
        val name: String,
        val xp: String?,
        val belief: String?,
        val group: String?,
        val world: String?,
        val faction: String?,
        val status: String,
        // Labels
        val xpLabel: String,
        val beliefLabel: String,
        val groupLabel: String,
        val worldLabel: String,
        val factionLabel: String,
        val statusLabel: String,
        // Tab labels
        val tabSkills: String,
        val tabConditions: String,
        val tabItems: String,
        val tabPowers: String,
        // Sub-section headers
        val powersHeader: String,
        val runeImbuesHeader: String,
        val glyphImbuesHeader: String,
        // Tab content
        val skills: List<CharacterSkillDisplay>,
        val conditions: List<CharacterConditionDisplay>,
        val items: List<CharacterItemDisplay>,
        val powers: List<CharacterPowerDisplay>,
        val runeImbues: List<CharacterImbueDisplay>,
        val glyphImbues: List<CharacterImbueDisplay>,
        // Empty state messages
        val emptySkills: String,
        val emptyConditions: String,
        val emptyItems: String,
        val emptyPowers: String,
        // Energy totals — null while loading, empty list when loaded with no energy sources
        val energyTotals: List<EnergyTotalDisplay>?,
        val energyLabel: String,
        // Back button
        val backButton: String,
        // Settings menu
        val switchCharacterButton: String,
        val logoutButton: String,
        val logoutConfirmMessage: String,
        val logoutConfirmButton: String,
        val logoutCancelButton: String,
    ) : CharacterDetailScreenDisplay()

    data class Error(
        val message: String,
        val retryButton: String,
        val backButton: String,
    ) : CharacterDetailScreenDisplay()
}

data class CharacterSkillDisplay(
    val id: Int,
    val name: String,
    val times: Int,
    val cost: Int,
    val manaAmount: Int?,
    val manatypeName: String?,
    val loresheet: Boolean,
    val costLabel: String,
    val timesLabel: String,
    val manaLabel: String,
    val loresheetLabel: String,
    val loresheetUrl: String? = null,
    val isExpanded: Boolean = false,
)

data class CharacterConditionDisplay(
    val coin: Int,
    val name: String,
    val expiry: String?,
    val expiryLabel: String,
    val noExpiry: String,
    val isExpanded: Boolean = false,
    val isLoadingDetail: Boolean = false,
    val playerText: String? = null,
    // Pre-fetched during energy totals load — no second API call needed on expand
    val manaAmount: Int? = null,
    val manatypeName: String? = null,
)

data class CharacterItemDisplay(
    val name: String,
    val itin: Int,
    val expiry: String?,
    val expiryLabel: String,
    val noExpiry: String,
    val isExpanded: Boolean = false,
    val isLoadingDetail: Boolean = false,
    val description: String? = null,
    val playerText: String? = null,
    // Pre-fetched during energy totals load — no second API call needed on expand
    val manaAmount: Int? = null,
    val manatypeName: String? = null,
    val imbueCapacity: Int? = null,
)

data class CharacterPowerDisplay(
    val poin: Int,
    val name: String,
    val expiry: String?,
    val expiryLabel: String,
    val noExpiry: String,
    val isExpanded: Boolean = false,
    val isLoadingDetail: Boolean = false,
    val playerText: String? = null,
    // Pre-fetched during energy totals load — no second API call needed on expand
    val manaAmount: Int? = null,
    val manatypeName: String? = null,
)

data class EnergyTotalDisplay(
    val manatypeName: String,
    val total: Int,
)

data class CharacterImbueDisplay(
    val name: String?,
    val expiry: String?,
    val expiryLabel: String,
    val noExpiry: String,
)

sealed class CharacterDetailEvent {
    data object Back : CharacterDetailEvent()
    data object Retry : CharacterDetailEvent()
    data object SwitchCharacter : CharacterDetailEvent()
    data object Logout : CharacterDetailEvent()
    data class ExpandSkill(val id: Int) : CharacterDetailEvent()
    data class ExpandCondition(val coin: Int) : CharacterDetailEvent()
    data class ExpandPower(val poin: Int) : CharacterDetailEvent()
    data class ExpandItem(val itin: Int) : CharacterDetailEvent()
    data class RechargeItem(val itin: Int) : CharacterDetailEvent()
}
