package com.coding.va.selfhelp.domain.model

import kotlinx.serialization.Serializable

@Serializable
data class CraftResourceEntry(
    val resourceAmount: String,
    val resourceType: String,
    val energyAmount: String,
    val energyType: String,
    val plin: String = "",
    val chin: String = "",
)

@Serializable
data class ImbueResourceEntry(
    val energyAmount: String,
    val energyType: String,
    val imbueTypeId: String = "",
    val imbueOptionName: String = "",
    val amount: String = "1",
    val skillSpell: String = "",
    val headImbuerPlin: String = "",
    val headImbuerChin: String = "",
    val suppliers: List<SerializedSupplier> = emptyList(),
)

/** Serializable snapshot of [ImbueEnergySupplier] (which uses non-serializable Pair). */
@Serializable
data class SerializedSupplier(
    val amount: String,
    val plin: String = "",
    val chin: String = "",
)

@Serializable
data class VortexItemCardDisplay(
    val header: String,
    val itemName: String? = null,
    val itemDescription: String? = null,
    val energyUsed: Map<EnergyType, Int>? = null,
    val craftResources: List<CraftResourceEntry>? = null,
    val imbueResourceEntries: List<ImbueResourceEntry>? = null,
    val tempItin: String? = null,
    val imbueId: String? = null,
    val targetItin: String? = null,
    val targetPlin: String? = null,
    val createdBy: String,
    val imbueCap: String? = null,
    val power: String? = null,
    /**
     * The skill a research book is for, typed by the crafter. Absent on cards made
     * before the field existed — the verify desk falls back to the notes column
     * there, which is where operators used to write it by hand.
     */
    val skillName: String? = null,
    val event: String = "",
)

fun VortexItemCardDisplay.getEasyName(type: EntryType): String? {
    return when (type) {
        EntryType.CRAFT_ITEM -> itemName
        EntryType.IMBUE_ITEM -> "$targetItin - $power"
        EntryType.RECHARGE_ITEM -> targetItin
        EntryType.IMBUE_PERSON -> "$targetPlin - $power"
        EntryType.MUNDANE_ITEM -> itemName
        EntryType.LAND_MANDATE,
        EntryType.PEOPLE_MANDATE,
        EntryType.MILITARY_ORDERS -> null
    }
}
