package com.coding.va.selfhelp.presentation.screens.mainscreen.actions

import androidx.lifecycle.viewModelScope
import androidx.navigation.NavHostController
import com.coding.va.selfhelp.presentation.screens.mainscreen.destinations.MainDestinations
import com.coding.va.selfhelp.presentation.screens.success.model.SuccessData
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.flow.MutableSharedFlow
import kotlinx.coroutines.flow.asSharedFlow
import kotlinx.coroutines.launch

class MainActions(
    private val navController: NavHostController,
    val doSomeThing: () -> Unit
) {
    fun home() {
        navController.popBackStack(MainDestinations.Landing, inclusive = false)
    }

    fun back() {
        navController.popBackStack()
    }

    fun navigate(direction: MainDestinations) {
        navController.navigate(direction)
    }
}