package com.coding.va.selfhelp.domain.use_cases

import com.coding.va.selfhelp.domain.model.MandateForm
import com.coding.va.selfhelp.domain.model.SheetEntryData
import com.coding.va.selfhelp.domain.respository.SheetsRepository
import org.koin.core.annotation.Factory
import org.koin.core.component.KoinComponent

@Factory
class SubmitMandateForm(private val repository: SheetsRepository) : KoinComponent {

    suspend operator fun invoke(form: MandateForm): Result<SheetEntryData> {
        return repository.addMandate(form)
    }
}
