package com.coding.va.selfhelp.presentation.screens.mandate.common

import com.coding.va.selfhelp.domain.model.MandateForm

/**
 * Required-field rules per mandate variant. All mandates share the OC Naam /
 * PLIN / Your name top-box fields; each variant adds its own subject field.
 */
fun MandateForm.isValid(): Boolean = when (this) {
    is MandateForm.Land -> hasBaseFields() && landName.isNotBlank()
    is MandateForm.People -> hasBaseFields() && peopleName.isNotBlank()
    is MandateForm.Military -> hasBaseFields() && regimentName.isNotBlank()
}

private fun MandateForm.hasBaseFields(): Boolean =
    ocName.isNotBlank() &&
        plin.first.isNotBlank() && plin.second.isNotBlank() &&
        characterName.isNotBlank()
