package com.coding.va.selfhelp.data.network

import co.touchlab.kermit.Logger
import com.coding.va.selfhelp.data.di.ERU_CLIENT
import com.coding.va.selfhelp.data.models.EruProfileEntity
import com.coding.va.selfhelp.data.models.EruTokenResponseEntity
import com.coding.va.selfhelp.di.ERU_KEYCLOAK_CLIENT_ID
import com.coding.va.selfhelp.di.currentEruEnvironment
import io.ktor.client.HttpClient
import io.ktor.client.call.body
import io.ktor.client.request.bearerAuth
import io.ktor.client.request.forms.submitForm
import io.ktor.client.request.get
import io.ktor.http.parameters
import org.koin.core.annotation.Named
import org.koin.core.annotation.Single

private val log = Logger.withTag("EruAuthApi")

@Single
class EruAuthApiImp(
    @Named(ERU_CLIENT) private val eruClient: HttpClient,
) : EruAuthApi {

    override suspend fun getProfile(accessToken: String): EruProfileEntity {
        val url = "${currentEruEnvironment.apiUrl}/api/me/profile"
        log.d { "EruAuth - GET $url" }
        val response = eruClient.get(url) { bearerAuth(accessToken) }
        log.d { "EruAuth - GET /api/me/profile → status=${response.status}" }
        return response.body()
    }

    override suspend fun exchangeCodeForTokens(
        code: String,
        redirectUri: String,
        codeVerifier: String?,
    ): EruTokenResponseEntity {
        log.d { "EruAuth - exchangeCodeForTokens: code=${code.take(8)}… redirectUri=$redirectUri" }
        val response = eruClient.submitForm(
            url = "${currentEruEnvironment.baseUrl}/protocol/openid-connect/token",
            formParameters = parameters {
                append("grant_type", "authorization_code")
                append("client_id", ERU_KEYCLOAK_CLIENT_ID)
                append("code", code)
                append("redirect_uri", redirectUri)
                if (codeVerifier != null) append("code_verifier", codeVerifier)
            },
        )
        log.d { "EruAuth - exchangeCodeForTokens → status=${response.status}" }
        return response.body()
    }

    override suspend fun refreshTokens(refreshToken: String): EruTokenResponseEntity {
        log.d { "EruAuth - refreshTokens: refreshToken=${refreshToken.take(8)}…" }
        val response = eruClient.submitForm(
            url = "${currentEruEnvironment.baseUrl}/protocol/openid-connect/token",
            formParameters = parameters {
                append("grant_type", "refresh_token")
                append("client_id", ERU_KEYCLOAK_CLIENT_ID)
                append("refresh_token", refreshToken)
            },
        )
        log.d { "EruAuth - refreshTokens → status=${response.status}" }
        return response.body()
    }

    override suspend fun endSession(refreshToken: String) {
        log.d { "EruAuth - endSession: refreshToken=${refreshToken.take(8)}…" }
        val response = eruClient.submitForm(
            url = "${currentEruEnvironment.baseUrl}/protocol/openid-connect/logout",
            formParameters = parameters {
                append("client_id", ERU_KEYCLOAK_CLIENT_ID)
                append("refresh_token", refreshToken)
            },
        )
        log.d { "EruAuth - endSession → status=${response.status}" }
    }
}