package com.coding.va.selfhelp.domain.model

enum class MundaneSkill(
    val resources: String,
    val requiresTargetPlin: Boolean,
    val requiresSecondPlin: Boolean,
    /** Inspiration required per item. Multiplied by quantity when hasQuantity is true. */
    val requiredInspiration: Int,
    /** When true the form shows a quantity field and multiplies inspiration/resources accordingly. */
    val hasQuantity: Boolean,
    /**
     * When true the form asks which skill is being researched, and will not submit
     * without it. The verify desk writes that name into the remark it puts on the
     * player, so an unnamed skill leaves a remark nobody can act on a year later.
     */
    val requiresSkillName: Boolean = false,
) {
    SCROLL_PAPER(
        resources = "3 Inspiration  OR  2 Mythical Paper",
        requiresTargetPlin = false,
        requiresSecondPlin = false,
        requiredInspiration = 3,
        hasQuantity = true,
    ),
    SKILL_RESEARCH_BOOK(
        resources = "12 Inspiration  OR  3 Mythical Vellum",
        requiresTargetPlin = true,
        requiresSecondPlin = false,
        requiredInspiration = 12,
        hasQuantity = false,
        requiresSkillName = true,
    ),
    BOOK_OF_EXPERIENCES(
        resources = "20 Inspiration  OR  1 Mythical Griffinskin Vellum",
        requiresTargetPlin = true,
        requiresSecondPlin = false,
        requiredInspiration = 20,
        hasQuantity = false,
    ),
    MARRIAGE_JEWELRY(
        resources = "13 Inspiration  OR  1 Gold Ingot",
        requiresTargetPlin = true,
        requiresSecondPlin = true,
        requiredInspiration = 13,
        hasQuantity = false,
    ),
}
