package com.coding.va.selfhelp.data.respository

import com.coding.va.selfhelp.BuildKonfig
import com.coding.va.selfhelp.data.models.ConfigResponse
import com.coding.va.selfhelp.data.network.BackendService
import com.coding.va.selfhelp.di.getPlatform
import com.coding.va.selfhelp.domain.model.MandateWindow
import com.coding.va.selfhelp.domain.respository.RemoteConfigRepository
import com.coding.va.selfhelp.utils.TYPE
import org.koin.core.annotation.Single
import kotlin.time.Clock
import kotlin.time.ExperimentalTime

/**
 * Event-window flags from the self-help backend (GET /api/v1/config). The
 * start/end-time logic lives server-side, so every client is up to date the
 * moment the admin changes the settings — no Remote Config polling or fetch
 * intervals. Desktop (the supervised kiosk) and debug builds bypass the
 * open/closed gate so staff can still process forms, but the real hours still
 * come from the server so the kiosk can show them.
 */
@Single
class BackendConfigRepository(
    private val service: BackendService,
) : RemoteConfigRepository {

    private var cached: Pair<Long, ConfigResponse>? = null

    override suspend fun canMakeCreation(): Result<Boolean> {
        if (bypass()) return Result.success(true)
        return loadConfig().map { it.canMakeCreation }
    }

    override suspend fun canSubmitMandate(): Result<Boolean> {
        if (bypass()) return Result.success(true)
        return loadConfig().map { it.canSubmitMandate }
    }

    @OptIn(ExperimentalTime::class)
    override suspend fun mandateWindow(): Result<MandateWindow> {
        return loadConfig().map { config ->
            MandateWindow(
                canSubmit = if (bypass()) true else config.canSubmitMandate,
                opensAtEpochSeconds = config.mandateOpensAtEpochSeconds,
                closesAtEpochSeconds = config.mandateClosesAtEpochSeconds,
            )
        }
    }

    @OptIn(ExperimentalTime::class)
    private suspend fun loadConfig(): Result<ConfigResponse> {
        val nowMs = Clock.System.now().toEpochMilliseconds()
        cached?.let { (atMs, value) ->
            if (nowMs - atMs < CACHE_TTL_MS) return Result.success(value)
        }
        return service.getConfig().onSuccess { cached = nowMs to it }
    }

    private fun bypass(): Boolean = getPlatform() == TYPE.DESKTOP || BuildKonfig.isDebug

    private companion object {
        const val CACHE_TTL_MS = 15_000L
    }
}
