package com.coding.va.selfhelp.presentation.screens.imbue

import com.coding.va.selfhelp.domain.model.EnergyType
import com.coding.va.selfhelp.i18n.AppStrings
import com.coding.va.selfhelp.i18n.localizedName
import com.coding.va.selfhelp.presentation.components.errorbox.model.ErrorBoxDisplay
import com.coding.va.selfhelp.presentation.components.plinfield.model.PlinFieldDisplay
import com.coding.va.selfhelp.presentation.components.selectablefield.model.SelectableFieldContent
import com.coding.va.selfhelp.presentation.components.selectablefield.model.SelectableFieldDisplay
import com.coding.va.selfhelp.presentation.screens.imbue.model.ImbueDisplay
import com.coding.va.selfhelp.presentation.screens.imbue.model.ImbueForm
import com.coding.va.selfhelp.presentation.screens.imbue.model.ImbueResourceDisplay
import com.coding.va.selfhelp.presentation.screens.imbue.model.ImbueResourceForm
import com.coding.va.selfhelp.presentation.screens.model.FieldDisplay

object ImbueDisplayProvider {

    fun provide(isPerson: Boolean, strings: AppStrings) = ImbueDisplay(
        title = if (isPerson) strings.imbue.titlePerson else strings.imbue.titleItem,
        description = strings.imbue.description,
        imbueDescription = if (isPerson) strings.imbue.imbueDescriptionPerson
        else strings.imbue.imbueDescriptionItem,
        isPerson = isPerson,
        imbueNotes = FieldDisplay(
            label = strings.common.specialNotesLabel,
            hint = strings.common.specialNotesHint,
        ),
        imbueTarget = if (isPerson) {
            PlinFieldDisplay(
                plinLabel = strings.imbue.receiverPlinLabel,
                plinHint = strings.imbue.receiverPlinHint,
                chinLabel = strings.common.chinLabel,
                chinHint = strings.common.chinLabel,
            )
        } else {
            PlinFieldDisplay(
                plinLabel = strings.imbue.itemItinLabel,
                plinHint = strings.imbue.itemItinHint,
                chinLabel = "",
                chinHint = ""
            )
        },
        imbueResource = provideEmptyImbueResource(isPerson, strings),
        form = ImbueForm(
            isPerson = isPerson,
            targetItin = if (isPerson) null else "",
            targetPlin = if (isPerson) Pair("", "") else null,
            notes = "",
            imbueResources = mutableMapOf(1 to ImbueResourceForm())
        ),
        shouldValidate = false,
        errorBox = null,
        imbueEffectNumber = strings.imbue.imbueEffectNumber,
        validate = strings.imbue.nextButton,
        backButton = strings.common.backToHome,
        verifySheet = null,
    )

    fun provideEmptyImbueResource(isPerson: Boolean, strings: AppStrings) = ImbueResourceDisplay(
        imbueType = SelectableFieldDisplay(
            label = strings.imbue.selectImbueLabel,
            content = ImbueTypes.getAllImbueTypes(isPerson, strings).map {
                SelectableFieldContent(
                    it.displayName,
                    it.id
                )
            }
        ),
        imbueOption = SelectableFieldDisplay(
            label = strings.imbue.selectOptionsLabel,
            enabled = false,
            content = emptyList()
        ),
        amount = FieldDisplay(
            label = strings.common.amountLabel,
            hint = strings.imbue.imbueAmountHint,
        ),
        energyAmount = FieldDisplay(
            label = strings.common.energyLabel,
            hint = strings.common.energyHint,
            enabled = false
        ),
        skillSpell = FieldDisplay(
            label = strings.imbue.skillSpellLabel,
            hint = strings.imbue.skillSpellHint,
            visible = false,
        ),
        custom = FieldDisplay(
            label = strings.imbue.customImbueLabel,
            hint = strings.imbue.customImbueHint,
            visible = false,
        ),
        energyType = SelectableFieldDisplay(
            label = strings.common.selectEnergyTypeLabel,
            content = EnergyType.entries.map {
                SelectableFieldContent(
                    it.localizedName(strings),
                    it.name
                )
            }
        ),
        plin = PlinFieldDisplay(
            plinLabel = strings.common.plinLabel,
            plinHint = strings.imbue.imbuerPlinHint,
            chinLabel = strings.common.chinLabel,
            chinHint = ""
        ),
        energySupplierDescription = strings.common.energySupplierDescription,
        currentEnergyLabel = strings.common.currentEnergyLabel,
        energySupplierAmount = FieldDisplay(
            label = strings.common.amountLabel,
            hint = strings.common.energySupplierAmountHint,
        ),
        energySupplierPlin = PlinFieldDisplay(
            plinLabel = strings.common.plinLabel,
            plinHint = strings.common.energySupplierPlinHint,
            chinLabel = strings.common.chinLabel,
            chinHint = ""
        )
    )

    fun requiredError(strings: AppStrings) = ErrorBoxDisplay(
        title = strings.common.requiredErrorTitle,
        description = strings.common.requiredErrorDescription,
        acceptButton = null,
        retryButton = strings.common.requiredErrorButton,
    )
}
