private val vortexRed = crimson

@Composable
fun CharacterDetailContent(
    display: CharacterDetailScreenDisplay.Display,
    onEvent: (CharacterDetailEvent) -> Unit,
) {
    val typography = VortexTypography()
    val tabs = listOf(
        display.tabSkills,
        display.tabConditions,
        display.tabItems,
        display.tabPowers,
    )
    var selectedTabIndex by remember { mutableStateOf(0) }

    val isDesktop = getPlatform() == TYPE.DESKTOP

    Column(modifier = Modifier.fillMaxWidth().padding(horizontal = 24.dp)) {
        // -- char-head (oxblood gradient, no avatar) --
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .padding(top = 16.dp)
                .clip(RoundedCornerShape(VortexRadius.lg))
                .background(Brush.linearGradient(listOf(Color(0xFF7A0A0A), crest)))
                .padding(24.dp),
        ) {
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.Top,
            ) {
                Column(modifier = Modifier.weight(1f).padding(end = 12.dp)) {
                    Text(
                        text = display.name,
                        style = TextStyle(fontFamily = DisplayFamily(), fontWeight = FontWeight.Bold, fontSize = 26.sp, lineHeight = 31.sp),
                        color = pureWhite,
                        modifier = Modifier.semantics { heading() },
                    )
                    val sub = listOfNotNull(display.faction, display.world).joinToString(" · ")
                    if (sub.isNotBlank()) {
                        Text(
                            text = sub,
                            style = TextStyle(fontFamily = BodyFamily(), fontSize = 14.sp),
                            color = giltLight,
                            modifier = Modifier.padding(top = 4.dp),
                        )
                    }
                }
                CharacterSettingsMenu(
                    switchCharacterLabel = display.switchCharacterButton,
                    logoutLabel = display.logoutButton,
                    logoutConfirmMessage = display.logoutConfirmMessage,
                    logoutConfirmButton = display.logoutConfirmButton,
                    logoutCancelButton = display.logoutCancelButton,
                    onSwitchCharacter = { onEvent(CharacterDetailEvent.SwitchCharacter) },
                    onLogout = { onEvent(CharacterDetailEvent.Logout) },
                )
            }
        }

        // -- stat cards (XP / Belief / Group / Status) --
        Spacer(Modifier.height(16.dp))
        val stats = listOf(
            display.xpLabel to (display.xp ?: "—"),
            display.beliefLabel to (display.belief ?: "—"),
            display.groupLabel to (display.group ?: "—"),
            display.statusLabel to display.status,
        )
        if (isDesktop) {
            Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                stats.forEach { (k, v) -> StatCard(value = v, key = k, modifier = Modifier.weight(1f)) }
            }
        } else {
            Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                stats.chunked(2).forEach { rowStats ->
                    Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                        rowStats.forEach { (k, v) -> StatCard(value = v, key = k, modifier = Modifier.weight(1f)) }
                        if (rowStats.size == 1) Spacer(Modifier.weight(1f))
                    }
                }
            }
        }

        // -- energy totals --
        Spacer(Modifier.height(12.dp))
        EnergySection(label = display.energyLabel, totals = display.energyTotals)

        // -- Tabs --
        Spacer(Modifier.height(16.dp))
        ScrollableTabRow(
            selectedTabIndex = selectedTabIndex,
            backgroundColor = paper,
            contentColor = vortexRed,
            edgePadding = 0.dp,
            divider = { Divider(color = vellumLine2) },
        ) {
            tabs.forEachIndexed { index, title ->
                val active = selectedTabIndex == index
                Tab(
                    selected = active,
                    onClick = { selectedTabIndex = index },
                    text = {
                        Text(
                            text = title,
                            style = TextStyle(fontFamily = BodyFamily(), fontWeight = FontWeight.SemiBold, fontSize = 15.sp),
                            color = if (active) crimson else ink3,
                        )
                    },
                )
            }
        }

        Spacer(Modifier.height(20.dp))

        // -- Tab content --
        when (selectedTabIndex) {
            0 -> SkillsTab(display.skills, display.emptySkills, onEvent)
            1 -> ConditionsTab(display.conditions, display.emptyConditions, onEvent)
            2 -> ItemsTab(display.items, display.emptyItems, onEvent)
            3 -> PowersTab(
                powers = display.powers,
                runeImbues = display.runeImbues,
                glyphImbues = display.glyphImbues,
                powersHeader = display.powersHeader,
                runeImbuesHeader = display.runeImbuesHeader,
                glyphImbuesHeader = display.glyphImbuesHeader,
                emptyMessage = display.emptyPowers,
                onEvent = onEvent,
            )
        }
    }
}

// ---------------------------------------------------------------------------
// Settings menu — lives in the char-head, matching the landing top-bar pattern
// ---------------------------------------------------------------------------

@Composable
private fun CharacterSettingsMenu(
    switchCharacterLabel: String,
    logoutLabel: String,
    logoutConfirmMessage: String,
    logoutConfirmButton: String,
    logoutCancelButton: String,
    onSwitchCharacter: () -> Unit,
    onLogout: () -> Unit,
) {
    var menuExpanded by remember { mutableStateOf(false) }
    var showLogoutConfirmation by remember { mutableStateOf(false) }
    val a11y = LocalStrings.current.a11y
    val typography = VortexTypography()

    if (showLogoutConfirmation) {
        AlertDialog(
            onDismissRequest = { showLogoutConfirmation = false },
            title = { Text(text = logoutLabel, style = typography.headlineSmall) },
            text = { Text(text = logoutConfirmMessage, style = typography.bodyMedium) },
            confirmButton = {
                VortexMaterialButton(onClick = {
                    showLogoutConfirmation = false
                    onLogout()
                }) {
                    Text(text = logoutConfirmButton)
                }
            },
            dismissButton = {
                VortexMaterialButton(onClick = { showLogoutConfirmation = false }) {
                    Text(text = logoutCancelButton)
                }
            },
        )
    }

    Box {
        UnstyledDropdownMenu(onExpandRequest = { menuExpanded = true }) {
            TopBarPill(
                text = "⚙",
                onClick = { menuExpanded = !menuExpanded },
                modifier = Modifier.semantics {
                    role = Role.Button
                    contentDescription = a11y.settingsMenu
                },
            )
            UnstyledDropdownMenuPanel(
                expanded = menuExpanded,
                onDismissRequest = { menuExpanded = false },
                modifier = Modifier
                    .padding(vertical = 4.dp)
                    .width(240.dp)
                    .shadow(4.dp, RoundedCornerShape(VortexRadius.md))
                    .clip(RoundedCornerShape(VortexRadius.md))
                    .background(paperRaised),
                enter = scaleIn(
                    animationSpec = tween(durationMillis = 120, easing = LinearOutSlowInEasing),
                    initialScale = 0.8f,
                    transformOrigin = TransformOrigin(1f, 0f),
                ) + fadeIn(tween(durationMillis = 30)),
                exit = scaleOut(
                    animationSpec = tween(durationMillis = 1, delayMillis = 75),
                    targetScale = 1f,
                ) + fadeOut(tween(durationMillis = 75)),
            ) {
                Column(modifier = Modifier.padding(vertical = 4.dp)) {
                    CharacterSettingsMenuItem(
                        label = switchCharacterLabel,
                        onClick = {
                            menuExpanded = false
                            onSwitchCharacter()
                        },
                    )
                    CharacterSettingsMenuItem(
                        label = logoutLabel,
                        onClick = {
                            menuExpanded = false
                            showLogoutConfirmation = true
                        },
                    )
                }
            }
        }
    }
}

@Composable
private fun CharacterSettingsMenuItem(label: String, onClick: () -> Unit) {
    Text(
        text = label,
        style = TextStyle(fontFamily = BodyFamily(), fontSize = 15.sp, fontWeight = FontWeight.Medium),
        color = ink,
        modifier = Modifier
            .fillMaxWidth()
            .clickable(onClick = onClick)
            .padding(horizontal = 16.dp, vertical = 12.dp),
    )
}

// ---------------------------------------------------------------------------
// Info row
// ---------------------------------------------------------------------------

@Composable
private fun StatCard(value: String, key: String, modifier: Modifier = Modifier) {
    Column(
        modifier = modifier
            .clip(RoundedCornerShape(VortexRadius.md))
            .background(paperRaised)
            .border(1.dp, vellumLine, RoundedCornerShape(VortexRadius.md))
            .padding(vertical = 14.dp, horizontal = 8.dp),
        horizontalAlignment = Alignment.CenterHorizontally,
    ) {
        Text(
            text = value,
            style = TextStyle(
                fontFamily = DisplayFamily(),
                fontWeight = FontWeight.Bold,
                fontSize = 22.sp,
                lineHeight = 26.sp,
            ),
            color = crimson,
            textAlign = androidx.compose.ui.text.style.TextAlign.Center,
        )
        Text(
            text = key.uppercase(),
            style = TextStyle(fontFamily = BodyFamily(), fontSize = 12.sp, letterSpacing = 0.6.sp),
            color = ink3,
            textAlign = androidx.compose.ui.text.style.TextAlign.Center,
            modifier = Modifier.padding(top = 2.dp),
        )
    }
}

// ---------------------------------------------------------------------------
// Energy section — shown in the overview header
// ---------------------------------------------------------------------------

@Composable
private fun EnergySection(label: String, totals: List<EnergyTotalDisplay>?) {
    val typography = VortexTypography()
    Row(
        modifier = Modifier.fillMaxWidth(),
        verticalAlignment = Alignment.Top,
        horizontalArrangement = Arrangement.spacedBy(6.dp),
    ) {
        Text(
            text = "$label:",
            style = typography.bodySmall,
            color = secondaryTextColor,
            fontWeight = FontWeight.Medium,
        )
        when {
            totals == null -> {
                // Still loading
                CircularProgressIndicator(
                    modifier = Modifier.size(12.dp),
                    strokeWidth = 1.5.dp,
                    color = vortexRed,
                )
            }
            totals.isEmpty() -> {
                Text(text = "—", style = typography.bodySmall, color = secondaryTextColor)
            }
            else -> {
                // Wrap chips in a flow-like column
                Column(verticalArrangement = Arrangement.spacedBy(2.dp)) {
                    totals.forEach { entry ->
                        Row(horizontalArrangement = Arrangement.spacedBy(4.dp)) {
                            Text(
                                text = "•",
                                style = typography.bodySmall,
                                color = vortexRed,
                            )
                            Text(
                                text = "${entry.manatypeName}: ${entry.total}",
                                style = typography.bodySmall,
                                color = ink,
                            )
                        }
                    }
                }
            }
        }
    }
}

// ---------------------------------------------------------------------------
// Skills tab — tap to expand inline details (cost, mana, loresheet)
// ---------------------------------------------------------------------------

@Composable
private fun SkillsTab(
    skills: List<CharacterSkillDisplay>,
    emptyMessage: String,
    onEvent: (CharacterDetailEvent) -> Unit,
) {
    val typography = VortexTypography()
    if (skills.isEmpty()) {
        Text(
            text = emptyMessage,
            style = typography.bodyMedium,
            color = secondaryTextColor,
            modifier = Modifier.padding(vertical = 16.dp),
        )
        return
    }
    Column(
        modifier = Modifier.fillMaxWidth(),
        verticalArrangement = Arrangement.spacedBy(12.dp),
    ) {
        skills.forEach { skill ->
            SkillRow(skill, onToggle = { onEvent(CharacterDetailEvent.ExpandSkill(skill.id)) })
        }
    }
}

@Composable
private fun SkillRow(skill: CharacterSkillDisplay, onToggle: () -> Unit) {
    val typography = VortexTypography()
    val a11y = LocalStrings.current.a11y
    val hasDetails = skill.cost > 0 || skill.manaAmount != null || skill.loresheet
    Column(
        modifier = Modifier
            .fillMaxWidth()
            .clip(RoundedCornerShape(VortexRadius.lg)).background(paperRaised).border(1.dp, vellumLine, RoundedCornerShape(VortexRadius.lg)),
    ) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .then(
                    if (hasDetails) Modifier
                        .semantics {
                            role = Role.Button
                            stateDescription = if (skill.isExpanded) a11y.expanded else a11y.collapsed
                        }
                        .clickable(onClick = onToggle)
                    else Modifier
                )
                .padding(16.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.SpaceBetween,
        ) {
            Text(
                text = if (skill.times > 1) "${skill.times}${skill.timesLabel} ${skill.name}"
                else skill.name,
                style = TextStyle(fontFamily = DisplayFamily(), fontWeight = FontWeight.SemiBold, fontSize = 17.sp),
                color = ink,
                modifier = Modifier.weight(1f),
            )
            if (hasDetails) {
                Text(
                    text = if (skill.isExpanded) "▲" else "▼",
                    style = typography.bodySmall,
                    color = vortexRed,
                )
            }
        }

        AnimatedVisibility(
            visible = skill.isExpanded,
            enter = expandVertically(),
            exit = shrinkVertically(),
        ) {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(start = 16.dp, end = 16.dp, bottom = 16.dp),
                verticalArrangement = Arrangement.spacedBy(4.dp),
            ) {
                Divider(color = dividerColor)
                Spacer(Modifier.height(2.dp))
                if (skill.cost > 0) {
                    Text(
                        text = "${skill.costLabel}: ${skill.cost} XP",
                        style = typography.bodySmall,
                        color = ink2,
                    )
                }
                if (skill.manaAmount != null && skill.manatypeName != null) {
                    Text(
                        text = "${skill.manaLabel}: ${skill.manaAmount} ${skill.manatypeName}",
                        style = typography.bodySmall,
                        color = ink2,
                    )
                }
                if (skill.loresheet) {
                    if (skill.loresheetUrl != null) {
                        Text(
                            text = "✦ ${skill.loresheetLabel}",
                            style = typography.bodySmall,
                            color = vortexRed,
                            textDecoration = TextDecoration.Underline,
                            modifier = Modifier.clickable { openInAppBrowser(skill.loresheetUrl) },
                        )
                    } else {
                        Text(
                            text = "✦ ${skill.loresheetLabel}",
                            style = typography.bodySmall,
                            color = vortexRed,
                        )
                    }
                }
            }
        }
    }
}

