package com.coding.va.selfhelp.presentation.methods

import androidx.navigation.NavType
import androidx.savedstate.SavedState
import androidx.savedstate.read
import androidx.savedstate.write
import kotlin.io.encoding.Base64
import kotlin.io.encoding.ExperimentalEncodingApi
import kotlinx.serialization.KSerializer
import kotlinx.serialization.json.Json

class GenericNavType<T : Any>(
    private val serializer: KSerializer<T>,
    isNullableAllowed: Boolean = false
) : NavType<T>(isNullableAllowed) {

    override fun get(bundle: SavedState, key: String): T? {
        return if (bundle.read { contains(key) }) {
            Json.decodeFromString(serializer, bundle.read { getString(key) })
        } else null
    }

    /**
     * Decoded from Base64 (URL-safe variant) back into JSON, then into the object.
     * This is the inverse of [serializeAsValue].
     */
    @OptIn(ExperimentalEncodingApi::class)
    override fun parseValue(value: String): T {
        val json = Base64.UrlSafe.decode(value).decodeToString()
        return Json.decodeFromString(serializer, json)
    }

    /**
     * Encode the JSON as URL-safe Base64 so that special characters in field values
     * (e.g. `?`, `#`, `&`, `.`) never break the Navigation route URL parsing.
     */
    @OptIn(ExperimentalEncodingApi::class)
    override fun serializeAsValue(value: T): String {
        val json = Json.encodeToString(serializer, value)
        return Base64.UrlSafe.encode(json.encodeToByteArray())
    }

    override fun put(bundle: SavedState, key: String, value: T) {
        bundle.write { putString(key, Json.encodeToString(serializer, value)) }
    }
}
