package com.coding.va.selfhelp.presentation.screens.mundane

import com.coding.va.selfhelp.domain.model.MundaneSkill
import com.coding.va.selfhelp.i18n.AppStrings
import com.coding.va.selfhelp.i18n.localizedName
import com.coding.va.selfhelp.presentation.components.errorbox.model.ErrorBoxDisplay
import com.coding.va.selfhelp.presentation.components.plinfield.model.PlinFieldDisplay
import com.coding.va.selfhelp.presentation.components.selectablefield.model.SelectableFieldContent
import com.coding.va.selfhelp.presentation.components.selectablefield.model.SelectableFieldDisplay
import com.coding.va.selfhelp.presentation.screens.model.FieldDisplay
import com.coding.va.selfhelp.presentation.screens.mundane.model.MundaneDisplay
import com.coding.va.selfhelp.presentation.screens.mundane.model.MundaneForm

object MundaneDisplayProvider {

    fun provide(strings: AppStrings) = MundaneDisplay(
        title = strings.mundane.title,
        description = strings.mundane.description,
        skillRequiredLabel = strings.mundane.skillRequiredLabel,
        skillResourcesLabel = strings.mundane.skillResourcesLabel,
        skillEffectLabel = strings.mundane.skillEffectLabel,
        inspirationSectionTitle = strings.mundane.inspirationSectionTitle,
        inspirationCountLabel = strings.mundane.inspirationCountLabel,
        backButton = strings.common.backToHome,
        nextButton = strings.mundane.nextButton,
        skillField = SelectableFieldDisplay(
            label = strings.mundane.selectSkillLabel,
            content = MundaneSkill.entries.map {
                SelectableFieldContent(displayValue = it.localizedName(strings), id = it.name)
            }
        ),
        crafterPlinField = PlinFieldDisplay(
            plinLabel = strings.common.plinLabel,
            plinHint = strings.mundane.crafterPlinHint,
            chinLabel = strings.common.chinLabel,
            chinHint = strings.common.chinLabel,
        ),
        quantityField = FieldDisplay(
            label = strings.mundane.quantityLabel,
            hint = strings.mundane.quantityHint,
        ),
        inspirationSupplierPlinField = PlinFieldDisplay(
            plinLabel = strings.common.plinLabel,
            plinHint = strings.mundane.supplierPlinHint,
            chinLabel = strings.common.chinLabel,
            chinHint = strings.common.chinLabel,
        ),
        inspirationSupplierAmountField = FieldDisplay(
            label = strings.mundane.inspirationLabel,
            hint = strings.mundane.inspirationAmountHint,
        ),
        inspirationSupplierDescription = strings.mundane.inspirationSupplierDescription,
        targetPlinField = PlinFieldDisplay(
            plinLabel = strings.common.plinLabel,
            plinHint = strings.mundane.targetPlinHint,
            chinLabel = strings.common.chinLabel,
            chinHint = strings.common.chinLabel,
        ),
        targetPlin2Field = PlinFieldDisplay(
            plinLabel = strings.common.plinLabel,
            plinHint = strings.mundane.targetPlin2Hint,
            chinLabel = strings.common.chinLabel,
            chinHint = strings.common.chinLabel,
        ),
        skillNameField = FieldDisplay(
            label = strings.mundane.skillNameLabel,
            hint = strings.mundane.skillNameHint,
        ),
        notesField = FieldDisplay(
            label = strings.common.specialNotesLabel,
            hint = strings.common.specialNotesHint,
        ),
        form = MundaneForm(),
        shouldValidate = false,
        errorBox = null,
        verifySheet = null,
    )

    fun requiredError(strings: AppStrings) = ErrorBoxDisplay(
        title = strings.common.requiredErrorTitle,
        description = strings.common.requiredErrorDescription,
        acceptButton = null,
        retryButton = strings.common.requiredErrorButton,
    )
}
