package com.coding.va.selfhelp.domain.model

// ---------------------------------------------------------------------------
// Domain models for the Characters feature
// ---------------------------------------------------------------------------

data class CharacterSummary(
    val plin: Int,
    val chin: Int,
    val name: String,
    val status: String,
)

data class CharacterDetail(
    val plin: Int,
    val chin: Int,
    val name: String,
    val xp: String?,
    val belief: String?,
    val group: String?,
    val world: String?,
    val status: String,
    val faction: String?,
    val items: List<CharacterItem>,
    val conditions: List<CharacterCondition>,
    val powers: List<CharacterPower>,
    val skills: List<CharacterSkill>,
    val runeImbues: List<CharacterRuneImbue>,
    val glyphImbues: List<CharacterGlyphImbue>,
)

data class CharacterItem(
    val itin: Int,
    val name: String,
    val expiry: String?,
    val deprecated: Boolean,
)

data class CharacterCondition(
    val coin: Int,
    val name: String,
    val expiry: String?,
    val deprecated: Boolean,
)

data class CharacterPower(
    val poin: Int,
    val name: String,
    val expiry: String?,
    val deprecated: Boolean,
)

data class CharacterSkill(
    val id: Int,
    val name: String,
    val times: Int,
    val cost: Int,
    val manaAmount: Int?,
    val manatypeName: String?,
    val loresheet: Boolean,
    val deprecated: Boolean,
)

data class CharacterRuneImbue(
    val name: String?,
    val expiry: String?,
)

data class CharacterGlyphImbue(
    val name: String?,
    val expiry: String?,
)

/** Represents the currently active character saved to local settings. */
data class ActiveCharacter(
    val plin: Int,
    val chin: Int,
)

/** Descriptive text fetched on demand for an item's detail page. */
data class ItemTextDetail(
    val description: String?,
    val playerText: String?,
)

/** A single mana pool total for one manatype, aggregated across skills, conditions, and powers. */
data class CharacterEnergyTotal(
    val manatypeName: String,
    val total: Int,
)

/** All detail fields fetched in one call when a power is expanded. */
data class PowerExpandData(
    val playerText: String?,
    val manaAmount: Int?,
    val manatypeName: String?,
)

/** All detail fields fetched in one call when a condition is expanded. */
data class ConditionExpandData(
    val playerText: String?,
    val manaAmount: Int?,
    val manatypeName: String?,
)

/** Mana and imbue data fetched from the detail endpoint of an item, power, or condition. */
data class EntityManaResult(
    val manaAmount: Int?,
    val manatypeName: String?,
    val imbueCapacity: Int? = null,
)

/** Full item detail used by the debug prod-item-probe screen. */
data class ProbeItemResult(
    val itin: Int,
    val name: String,
    val description: String?,
    val playerText: String?,
    /** PLIN of the owning player, or null if not attached to a player. */
    val ownerPlin: Int?,
    /** CHIN of the owning character, or null if not attached to a character. */
    val ownerChin: Int?,
    /** Display name of the owning character, or null if not available. */
    val ownerCharacterName: String?,
)
