package com.coding.va.selfhelp.presentation.screens.mandate.common

import com.coding.va.selfhelp.data.mapper.specialInstructionsText
import com.coding.va.selfhelp.data.mapper.subject
import com.coding.va.selfhelp.data.mapper.toFormFieldsText
import com.coding.va.selfhelp.domain.model.MandateForm
import com.coding.va.selfhelp.domain.model.SavedCreation
import com.coding.va.selfhelp.domain.model.SheetEntryData
import com.coding.va.selfhelp.i18n.AppStrings
import com.coding.va.selfhelp.i18n.localizedName

/**
 * Produce a [SavedCreation] for the creation-history screen. Mandates have no
 * printable card, so [SavedCreation.vortexCard] stays null; the formatted
 * field summary goes into resourcesText and the special instructions / other
 * advice goes into notes.
 */
fun MandateForm.toSavedCreation(entry: SheetEntryData, strings: AppStrings): SavedCreation =
    SavedCreation(
        cardCode = entry.getCardCode,
        name = entry.type.localizedName(strings),
        readableText = subject().takeIf { it.isNotBlank() },
        vortexCard = null,
        resourcesText = toFormFieldsText(),
        notes = specialInstructionsText().takeIf { it.isNotBlank() },
    )
