package com.coding.va.selfhelp.presentation.screens.imbue

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.coding.va.selfhelp.domain.use_cases.AddImbue
import com.coding.va.selfhelp.domain.use_cases.CanMakeCreation
import com.coding.va.selfhelp.domain.use_cases.GetActiveCharacterUseCase
import com.coding.va.selfhelp.i18n.AppStrings
import com.coding.va.selfhelp.domain.model.EnergyType
import com.coding.va.selfhelp.domain.model.ImbueOption
import com.coding.va.selfhelp.domain.model.ImbueResourceEntry
import com.coding.va.selfhelp.presentation.methods.ApiErrorDisplayProvider
import com.coding.va.selfhelp.presentation.screens.imbue.model.ImbueEnergySupplier
import com.coding.va.selfhelp.presentation.screens.imbue.model.ImbueEvent
import com.coding.va.selfhelp.presentation.screens.imbue.model.ImbueResourceForm
import com.coding.va.selfhelp.presentation.screens.imbue.model.isValid
import com.coding.va.selfhelp.presentation.screens.imbue.model.meetsMinRequirements
import com.coding.va.selfhelp.presentation.screens.imbue.model.toResourcesText
import com.coding.va.selfhelp.presentation.screens.imbue.model.toVerifySheet
import com.coding.va.selfhelp.presentation.screens.imbue.model.toVortexCard
import com.coding.va.selfhelp.presentation.screens.mainscreen.actions.MainActions
import com.coding.va.selfhelp.presentation.screens.mainscreen.destinations.MainDestinations
import com.coding.va.selfhelp.presentation.screens.success.model.SuccessData
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.serialization.json.Json
import kotlinx.coroutines.launch
import org.koin.android.annotation.KoinViewModel

@KoinViewModel
class ImbueViewModel(
    private val addImbueToSheet: AddImbue,
    private val canMakeCreation: CanMakeCreation,
    private val getActiveCharacter: GetActiveCharacterUseCase,
    private val strings: AppStrings,
) : ViewModel() {

    private val _display = MutableStateFlow(ImbueDisplayProvider.provide(false, strings))
    val display = _display.asStateFlow()

    private var mainActions: MainActions? = null
    private var isInitialized = false

    fun initVM(actions: MainActions, destination: MainDestinations.Imbue) {
        viewModelScope.launch {
            if (!isInitialized) {
                _display.emit(ImbueDisplayProvider.provide(destination.isPerson, strings))
                isInitialized = true
            }
            applyPrefill(destination)
            prefillActiveCharacter()
        }
        mainActions = actions
    }

    private fun prefillActiveCharacter() {
        val active = getActiveCharacter() ?: return
        val plin = Pair(active.plin.toString(), active.chin.toString())
        val currentForm = _display.value.form
        _display.value = _display.value.copy(
            form = currentForm.copy(
                imbueResources = currentForm.imbueResources.mapValues { (_, res) ->
                    res.copy(
                        headImbuerPlin = if (res.headImbuerPlin.first.isBlank()) plin else res.headImbuerPlin,
                        energySuppliers = res.energySuppliers.mapValues { (_, supplier) ->
                            if (supplier.plin.first.isBlank()) supplier.copy(plin = plin) else supplier
                        }
                    )
                }
            )
        )
    }

    private fun applyPrefill(dest: MainDestinations.Imbue) {
        if (dest.prefillEnergy.isBlank() && dest.prefillNotes.isBlank()
            && dest.prefillImbueResources.isBlank()) return

        val allImbueTypes = ImbueTypes.getAllImbueTypes(dest.isPerson, strings)
        val imbueResources = mutableMapOf<Int, ImbueResourceForm>()

        if (dest.prefillImbueResources.isNotBlank()) {
            val entries = try {
                Json.decodeFromString<List<ImbueResourceEntry>>(dest.prefillImbueResources)
            } catch (_: Exception) { emptyList() }

            entries.forEachIndexed { index, entry ->
                val energyType = EnergyType.entries.firstOrNull { it.name == entry.energyType } ?: EnergyType.SPIRITUAL_MANA
                val imbueType = allImbueTypes.firstOrNull { it.id == entry.imbueTypeId }
                val imbueOption = ImbueOption.entries.firstOrNull { it.name == entry.imbueOptionName }
                val suppliers = mutableMapOf<Int, ImbueEnergySupplier>()
                entry.suppliers.forEachIndexed { si, s ->
                    suppliers[si + 1] = ImbueEnergySupplier(
                        amount = s.amount,
                        plin = Pair(s.plin, s.chin),
                    )
                }
                if (suppliers.isEmpty()) {
                    suppliers[1] = ImbueEnergySupplier()
                }
                imbueResources[index + 1] = ImbueResourceForm(
                    amount = entry.amount,
                    imbueType = imbueType,
                    imbueOption = imbueOption,
                    skillSpell = entry.skillSpell,
                    energyAmount = entry.energyAmount,
                    energyType = energyType,
                    headImbuerPlin = Pair(entry.headImbuerPlin, entry.headImbuerChin),
                    energySuppliers = suppliers,
                )
            }
        } else if (dest.prefillEnergy.isNotBlank()) {
            dest.prefillEnergy.split(",").forEachIndexed { index, entry ->
                val (typeName, amount) = entry.split(":")
                val energyType = EnergyType.entries.firstOrNull { it.name == typeName } ?: EnergyType.SPIRITUAL_MANA
                imbueResources[index + 1] = ImbueResourceForm(
                    energyAmount = amount,
                    energyType = energyType,
                )
            }
        }
        if (imbueResources.isEmpty()) {
            imbueResources[1] = ImbueResourceForm()
        }

        val updatedForm = _display.value.form.copy(
            notes = dest.prefillNotes,
            imbueResources = imbueResources,
        )
        _display.value = _display.value.copy(form = updatedForm)
    }

    fun onEvent(event: ImbueEvent) {
        viewModelScope.launch {
            when (event) {
                is ImbueEvent.AddImbueResource -> {
                    _display.emit(
                        _display.value.copy(
                            form = _display.value.form.copy(
                                imbueResources = _display.value.form.imbueResources.toMutableMap()
                                    .apply {
                                        this[_display.value.form.imbueResources.size + 1] =
                                            ImbueResourceForm()
                                    }
                            )
                        )
                    )
                }

                is ImbueEvent.RemoveImbueResource -> {
                    _display.emit(
                        _display.value.copy(
                            form = _display.value.form.copy(
                                imbueResources = _display.value.form.imbueResources.toMutableMap()
                                    .apply { remove(event.row) }
                            )
                        )
                    )
                }

                is ImbueEvent.AddPowerSupplier -> {
                    _display.emit(
                        _display.value.copy(
                            form = _display.value.form.copy(
                                imbueResources = _display.value.form.imbueResources.toMutableMap()
                                    .apply {
                                        val size = this[event.resource]?.energySuppliers?.size ?: 1
                                        this[event.resource] = this[event.resource]?.copy(
                                            energySuppliers = (this[event.resource]?.energySuppliers?.toMutableMap() ?: mutableMapOf())
                                                .apply {
                                                    this[size + 1] = ImbueEnergySupplier()
                                                }
                                        ) ?: ImbueResourceForm()
                                    }
                            )
                        )
                    )
                }

                is ImbueEvent.RemovePowerSupplier -> {
                    _display.emit(
                        _display.value.copy(
                            form = _display.value.form.copy(
                                imbueResources = _display.value.form.imbueResources.toMutableMap()
                                    .apply {
                                        this[event.resource] = this[event.resource]?.copy(
                                            energySuppliers = (this[event.resource]?.energySuppliers?.toMutableMap() ?: mutableMapOf())
                                                .apply { remove(event.row) }
                                        ) ?: ImbueResourceForm()
                                    }
                            )
                        )
                    )
                }

                is ImbueEvent.UpdateImbueForm -> {
                    _display.emit(_display.value.copy(form = event.form))
                }

                is ImbueEvent.Back -> {
                    mainActions?.home()
                }

                is ImbueEvent.Verify -> {
                    when {
                        _display.value.form.isValid() -> {
                            _display.emit(
                                _display.value.copy(
                                    shouldValidate = false,
                                    verifySheet = _display.value.form.toVerifySheet(false, canMakeCreation().getOrNull() ?: false, strings)
                                )
                            )
                        }

                        _display.value.form.meetsMinRequirements() -> {
                            _display.emit(
                                _display.value.copy(
                                    shouldValidate = true,
                                    verifySheet = _display.value.form.toVerifySheet(true, canMakeCreation().getOrNull() ?: false, strings)
                                )
                            )
                        }

                        else -> {
                            _display.emit(
                                _display.value.copy(
                                    shouldValidate = true,
                                    errorBox = ImbueDisplayProvider.requiredError(strings)
                                )
                            )
                        }
                    }
                }

                is ImbueEvent.AddImbue -> {
                    addImbue()
                }

                is ImbueEvent.DismissError -> {
                    _display.emit(
                        _display.value.copy(
                            shouldValidate = true,
                            errorBox = null,
                            verifySheet = null,
                        )
                    )
                }
            }
        }
    }

    private fun addImbue() {
        viewModelScope.launch {
            _display.emit(
                _display.value.copy(
                    verifySheet = _display.value.verifySheet?.copy(
                        confirm = _display.value.verifySheet?.confirm?.copy(
                            loading = true
                        )!!
                    )
                )
            )
            addImbueToSheet(_display.value.form)
                .onSuccess {
                    mainActions?.navigate(
                        MainDestinations.Success(
                            data = SuccessData(
                                cardDisplay = _display.value.form.toVortexCard(it.itemId),
                                entryData = it,
                                resourcesText = _display.value.form.toResourcesText(),
                                notes = _display.value.form.notes,
                            )
                        )
                    )
                }.onFailure {
                    _display.emit(
                        _display.value.copy(
                            shouldValidate = false,
                            verifySheet = null,
                            errorBox = ApiErrorDisplayProvider.error(it.message, strings)
                        )
                    )
                }
        }
    }
}
