import com.coding.va.selfhelp.data.mapper.cardCodeToEntryData
import com.coding.va.selfhelp.data.mapper.formTypeKey
import com.coding.va.selfhelp.data.mapper.specialInstructionsText
import com.coding.va.selfhelp.data.mapper.subject
import com.coding.va.selfhelp.data.mapper.toEntryType
import com.coding.va.selfhelp.data.mapper.toFormFieldsText
import com.coding.va.selfhelp.data.mapper.toJsonPayload
import com.coding.va.selfhelp.data.mapper.toSheetsEntry
import com.coding.va.selfhelp.data.models.BackendApiJson
import com.coding.va.selfhelp.data.models.CardEntryPayload
import com.coding.va.selfhelp.data.models.EntryPayload
import com.coding.va.selfhelp.data.models.MandateEntryPayload
import com.coding.va.selfhelp.data.network.BackendService
import com.coding.va.selfhelp.data.mapper.englishEffect
import com.coding.va.selfhelp.data.mapper.plinToText
import com.coding.va.selfhelp.data.mapper.toResourcesText
import com.coding.va.selfhelp.data.mapper.toVortexCard
import com.coding.va.selfhelp.di.getPlatform
import com.coding.va.selfhelp.domain.model.EntryType
import com.coding.va.selfhelp.domain.model.ImbueForm
import com.coding.va.selfhelp.domain.model.ItemCraftForm
import com.coding.va.selfhelp.domain.model.MandateForm
import com.coding.va.selfhelp.domain.model.MundaneForm
import com.coding.va.selfhelp.domain.model.RechargeForm
import com.coding.va.selfhelp.domain.model.SheetEntryData
import com.coding.va.selfhelp.domain.model.SuccessData
import com.coding.va.selfhelp.domain.model.VortexItemCardDisplay
import com.coding.va.selfhelp.domain.respository.SheetsRepository
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.decodeFromJsonElement
import kotlinx.serialization.json.encodeToJsonElement
import kotlinx.serialization.json.jsonObject

import org.koin.core.annotation.Single

@Single
class SheetsRepositoryImp(
    private val service: BackendService,
) : SheetsRepository {

    private val json = BackendApiJson.instance

    override suspend fun setPrinted(entry: SheetEntryData): Result<Unit> {
        return service.markPrinted(entry)
    }

    override suspend fun addCraftedItem(form: ItemCraftForm): Result<SheetEntryData> {
        return Result.runCatching {
            val entry = createEntry(EntryType.CRAFT_ITEM).getOrThrow()
            writeCard(
                entry,
                card = form.toVortexCard(entry.itemId),
                itemName = form.name,
                itemDescription = form.description,
                imbueCap = form.imbueCap,
                resources = form.toResourcesText(),
                notes = form.notes,
            ).getOrThrow()
        }
    }

    override suspend fun addImbue(form: ImbueForm): Result<SheetEntryData> {
        return Result.runCatching {
            val entry = if (form.isPerson) {
                createEntry(EntryType.IMBUE_PERSON).getOrThrow()
            } else {
                createEntry(EntryType.IMBUE_ITEM).getOrThrow()
            }
            val vortexCard = form.toVortexCard(entry.itemId)
            writeCard(
                entry,
                card = vortexCard,
                itemName = form.targetItin ?: form.targetPlin?.plinToText().orEmpty(),
                imbue = vortexCard.power.orEmpty(),
                resources = form.toResourcesText(),
                notes = form.notes,
            ).getOrThrow()
        }
    }

    override suspend fun addRecharge(form: RechargeForm): Result<SheetEntryData> {
        return Result.runCatching {
            val entry = createEntry(EntryType.RECHARGE_ITEM).getOrThrow()
            writeCard(
                entry,
                card = form.toVortexCard(entry.itemId),
                itemName = form.targetItin,
                resources = form.toResourcesText(),
                notes = form.notes,
            ).getOrThrow()
        }
    }

    override suspend fun addMundaneItem(form: MundaneForm): Result<SheetEntryData> {
        return Result.runCatching {
            val entry = createEntry(EntryType.MUNDANE_ITEM).getOrThrow()
            val targetPlinText = when {
                form.selectedSkill?.requiresSecondPlin == true ->
                    "${form.targetPlin.plinToText()} + ${form.targetPlin2.plinToText()}"
                form.selectedSkill?.requiresTargetPlin == true ->
                    form.targetPlin.plinToText()
                else -> ""
            }
            writeCard(
                entry,
                card = form.toVortexCard(),
                itemName = targetPlinText,
                itemDescription = form.selectedSkill?.englishEffect().orEmpty(),
                resources = form.toResourcesText(), // skill name + quantity + crafter + inspiration
                notes = form.notes,
            ).getOrThrow()
        }
    }

    override suspend fun addMandate(form: MandateForm): Result<SheetEntryData> {
        return Result.runCatching {
            val entry = createEntry(form.toEntryType()).getOrThrow()
            val payload = MandateEntryPayload(
                cardCode = entry.getCardCode,
                platform = getPlatform().displayName,
                itemId = entry.itemId,
                form = json.parseToJsonElement(form.toJsonPayload()).jsonObject,
                formType = form.formTypeKey(),
                ocName = form.ocName,
                plin = form.plin.plinToText(),
                characterName = form.characterName,
                subject = form.subject(),
                formFields = form.toFormFieldsText(),
                specialInstructions = form.specialInstructionsText(),
            )
            service.writeEntry(entry, payload).map { entry }.getOrThrow()
        }
    }

    override suspend fun getPrintData(cardCode: String): Result<SuccessData> {
        return Result.runCatching {
            val entryData = cardCode.cardCodeToEntryData()
            val result = service.getEntry(entryData).getOrThrow()
            if (cardCode != result.cardCode) {
                throw Exception("Card code mismatch $cardCode - ${result.cardCode}")
            }
            val payload = result.payload ?: throw Exception("Entry $cardCode has no card payload")
            SuccessData(
                json.decodeFromJsonElement<VortexItemCardDisplay>(payload),
                SheetEntryData(
                    rowNumber = entryData.rowNumber,
                    itemId = result.itemId,
                    getCardCode = result.cardCode,
                    type = entryData.type,
                    alreadyPrinted = result.printed,
                )
            )
        }
    }

    private suspend fun createEntry(type: EntryType): Result<SheetEntryData> {
        return service.createEntry(type).map { it.toSheetsEntry(type) }
    }

    private suspend fun writeCard(
        entry: SheetEntryData,
        card: VortexItemCardDisplay,
        itemName: String = "",
        itemDescription: String = "",
        imbue: String = "",
        imbueCap: String = "",
        resources: String = "",
        notes: String = "",
    ): Result<SheetEntryData> {
        val payload: EntryPayload = CardEntryPayload(
            cardCode = entry.getCardCode,
            platform = getPlatform().displayName,
            itemId = entry.itemId,
            card = json.encodeToJsonElement(card).jsonObject,
            itemName = itemName,
            itemDescription = itemDescription,
            imbue = imbue,
            imbueCap = imbueCap,
            resources = resources,
            notes = notes,
        )
        return service.writeEntry(entry, payload).map { entry }
    }
}
