package com.coding.va.selfhelp.presentation.screens.character.select.model

sealed class CharacterSelectScreenDisplay {
    data object Loading : CharacterSelectScreenDisplay()

    data class Display(
        val title: String,
        val subtitle: String,
        val characters: List<CharacterSelectItemDisplay>,
        val backButton: String,
    ) : CharacterSelectScreenDisplay()

    data class Error(
        val message: String,
        val retryButton: String,
        val backButton: String,
    ) : CharacterSelectScreenDisplay()
}

data class CharacterSelectItemDisplay(
    val plin: Int,
    val chin: Int,
    val name: String,
    val statusLabel: String,
)

sealed class CharacterSelectEvent {
    data class SelectCharacter(val plin: Int, val chin: Int) : CharacterSelectEvent()
    data object Retry : CharacterSelectEvent()
    data object Back : CharacterSelectEvent()
}