fun ImbueOption.getEnergy(type: ImbueType?): Int {
    return if (type?.isUpgraded == true) {
        this.upgradedEnergy ?: this.energy
    } else {
        this.energy
    }
}

class ImbueType(
    val id: String,
    /** Localized name shown in the dropdown UI. */
    val displayName: String,
    /** Always-English name used in stored data (Google Drive, lammy text). */
    val englishName: String,
    val options: List<ImbueOption>,
    val multiplePossible: Boolean,
    val isUpgraded: Boolean,
    val canBePersonal: Boolean = true,
    val powerText: String,
    val canModifyEnergy: Boolean = false,
    val hasOpenPowerField: Boolean = false,
)