@Composable
fun VortexFamily() = DisplayFamily()

/**
 * App typography (Material 3). This is the workhorse — most screens call it directly as a local
 * `typography` rather than reading from MaterialTheme. Display/heading/title/label slots use Inknut;
 * body slots use Spectral. Kiosk floor: no body style below 16sp.
 */
@Composable
fun VortexTypography(): Material3Typography = Material3Typography().run {
    val display = DisplayFamily()
    val body = BodyFamily()
    copy(
        displayLarge = displayLarge.copy(fontFamily = display),
        displayMedium = displayMedium.copy(fontFamily = display),
        displaySmall = displaySmall.copy(fontFamily = display),
        headlineLarge = headlineLarge.copy(fontFamily = display, fontSize = 40.sp),
        headlineMedium = headlineMedium.copy(fontFamily = display),
        headlineSmall = headlineSmall.copy(fontFamily = display),
        titleLarge = titleLarge.copy(fontFamily = display, fontSize = 23.sp),
        titleMedium = titleMedium.copy(fontFamily = display),
        titleSmall = titleSmall.copy(fontFamily = display),
        bodyLarge = bodyLarge.copy(fontFamily = body, fontSize = 18.sp, fontWeight = FontWeight.Bold),
        bodyMedium = bodyMedium.copy(fontFamily = body, fontSize = 17.sp, lineHeight = 27.2.sp),
        bodySmall = bodySmall.copy(fontFamily = body, fontSize = 16.sp),
        labelLarge = labelLarge.copy(fontFamily = display, fontSize = 23.sp),
        labelMedium = labelMedium.copy(fontFamily = display),
        labelSmall = labelSmall.copy(fontFamily = display),
    )
}

/**
 * Material 2 typography — supplied to the M2 MaterialTheme in App.kt so M2 consumers
 * (SelectableField / PlinTextField read `MaterialTheme.typography.caption`) get Spectral and the
 * kiosk ≥16sp floor. Headings use Inknut, everything else Spectral.
 */
@Composable
fun VortexTypographyM2(): Material2Typography {
    val display = DisplayFamily()
    val body = BodyFamily()
    return Material2Typography(defaultFontFamily = body).run {
        copy(
            h1 = h1.copy(fontFamily = display),
            h2 = h2.copy(fontFamily = display),
            h3 = h3.copy(fontFamily = display),
            h4 = h4.copy(fontFamily = display),
            h5 = h5.copy(fontFamily = display),
            h6 = h6.copy(fontFamily = display),
            body1 = body1.copy(fontSize = 17.sp, lineHeight = 27.2.sp),
            caption = caption.copy(fontSize = 16.sp),
        )
    }
}

/** Mono style for PLIN / envelope / printer codes. Use directly (no Material slot for mono). */
@Composable
fun vortexMono(): TextStyle = TextStyle(
    fontFamily = MonoFamily(),
    fontSize = 17.sp,
    lineHeight = 27.2.sp,
)

// Used by the printed thermal card — intentionally left as-is (no font family) so the captured
// print output is unchanged. Do not retarget to a brand family.
val BodyBold = TextStyle.Default.copy(
    fontSize = 18.sp,
    fontWeight = FontWeight.Bold
)
