package com.coding.va.selfhelp.presentation.screens.mandate.select

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.coding.va.selfhelp.domain.use_cases.GetMandateWindow
import com.coding.va.selfhelp.i18n.LanguageRepository
import com.coding.va.selfhelp.presentation.screens.mandate.common.MandateHours
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch
import org.koin.android.annotation.KoinViewModel

@KoinViewModel
class MandateSelectViewModel(
    private val getMandateWindow: GetMandateWindow,
    private val languageRepository: LanguageRepository,
) : ViewModel() {

    data class HoursBanner(val title: String, val text: String)

    private val _hours = MutableStateFlow<HoursBanner?>(null)
    val hours = _hours.asStateFlow()

    init {
        viewModelScope.launch {
            val window = getMandateWindow().getOrNull()
            languageRepository.stringsFlow().collect { current ->
                _hours.value = window?.let { MandateHours.copy(it, current.mandate) }
                    ?.let { HoursBanner(it.title, it.description) }
            }
        }
    }
}
