@Composable
fun Modifier.placeholder(
    isLoading: Boolean,
    width: Float = 200f,
    colors: List<Color> = listOf(
        Color.Gray.copy(alpha = 0.2f),
        Color.Gray.copy(alpha = 0.4f),
        Color.Gray.copy(alpha = 0.2f)
    )
): Modifier {
    val reduceMotion = LocalReduceMotion.current
    val loadingLabel = LocalStrings.current.a11y.loading

    // Only animate when we actually need to — skip the infiniteTransition
    // allocation when reduce-motion is on or when we're not loading.
    val translateAnimation: Float = if (isLoading && !reduceMotion) {
        val infiniteTransition = rememberInfiniteTransition()
        val value by infiniteTransition.animateFloat(
            initialValue = -width,
            targetValue = width * 3,
            animationSpec = infiniteRepeatable(
                animation = tween(durationMillis = 1000, easing = LinearEasing),
                repeatMode = RepeatMode.Restart
            )
        )
        value
    } else {
        0f
    }

    if (!isLoading) return this

    val drawn = this.drawWithContent {
        val brush = if (reduceMotion) {
            // Static flat overlay — no motion, still hides content as "pending".
            Brush.linearGradient(colors = colors)
        } else {
            Brush.linearGradient(
                colors = colors,
                start = Offset(translateAnimation, 0f),
                end = Offset(translateAnimation + width, 0f),
            )
        }
        drawRoundRect(
            brush = brush,
            cornerRadius = CornerRadius.Zero.copy(8f, 8f),
            size = Size(size.width, size.height)
        )
    }
    return drawn.semantics {
        liveRegion = LiveRegionMode.Polite
        contentDescription = loadingLabel
    }
}

fun Modifier.moveFocusOnTab() = composed {
    val focusManager = LocalFocusManager.current
    onPreviewKeyEvent {
        if (it.type == KeyEventType.KeyDown && it.key == Key.Tab) {
            focusManager.moveFocus(
                if (it.isShiftPressed) FocusDirection.Previous else FocusDirection.Next
            )
            true
        } else {
            false
        }
    }
}
