package com.coding.va.selfhelp.data.mapper

import com.coding.va.selfhelp.domain.model.EntryType
import com.coding.va.selfhelp.domain.model.MandateForm
import com.coding.va.selfhelp.domain.model.MandateHelpHinderOther
import com.coding.va.selfhelp.domain.model.MandateYesNo
import com.coding.va.selfhelp.domain.model.MandateYesNoOther
import com.coding.va.selfhelp.domain.model.MilitaryAction
import kotlinx.serialization.json.Json

private val mandateJson = Json {
    ignoreUnknownKeys = true
    encodeDefaults = true
}

fun MandateForm.toEntryType(): EntryType = when (this) {
    is MandateForm.Land -> EntryType.LAND_MANDATE
    is MandateForm.People -> EntryType.PEOPLE_MANDATE
    is MandateForm.Military -> EntryType.MILITARY_ORDERS
}

fun MandateForm.formTypeKey(): String = when (this) {
    is MandateForm.Land -> "LAND_MANDATE"
    is MandateForm.People -> "PEOPLE_MANDATE"
    is MandateForm.Military -> "MILITARY_ORDERS"
}

fun MandateForm.subject(): String = when (this) {
    is MandateForm.Land -> landName
    is MandateForm.People -> peopleName
    is MandateForm.Military -> regimentName
}

fun MandateForm.specialInstructionsText(): String = when (this) {
    is MandateForm.Land -> specialInstructions
    is MandateForm.People -> otherAdvice
    is MandateForm.Military -> specialInstructions
}

fun MandateForm.toJsonPayload(): String = when (this) {
    is MandateForm.Land -> mandateJson.encodeToString(MandateForm.Land.serializer(), this)
    is MandateForm.People -> mandateJson.encodeToString(MandateForm.People.serializer(), this)
    is MandateForm.Military -> mandateJson.encodeToString(MandateForm.Military.serializer(), this)
}

/** Human-readable summary written to column K — mirrors PDF order of the form-specific fields. */
fun MandateForm.toFormFieldsText(): String = when (this) {
    is MandateForm.Land -> buildString {
        appendLine("Height of taxation: $taxationPer100 in every hundred pieces")
        appendLine("Spend first on: ${spendFirstOn.ifBlank { "(follow our advice)" }}")
        appendLine("Leftover spent on: ${spendLeftoverOn.ifBlank { "-" }}")
        append("Disband: ${disband.ifBlank { "-" }}")
    }
    is MandateForm.People -> buildString {
        val migrateWherePart = if (migrate == MandateYesNo.YES && migrateWhere.isNotBlank()) " — where: $migrateWhere" else ""
        appendLine("Migrate: ${migrate.label()}$migrateWherePart")
        val militiaOtherPart = if (militia == MandateYesNoOther.OTHER && militiaOther.isNotBlank()) " — $militiaOther" else ""
        appendLine("Maintain militia: ${militia.label()}$militiaOtherPart")
        val growOtherPart = if (grow == MandateYesNoOther.OTHER && growOther.isNotBlank()) " — $growOther" else ""
        appendLine("Grow numbers: ${grow.label()}$growOtherPart")
        val occupationOtherPart = if (occupationStance == MandateHelpHinderOther.OTHER && occupationOther.isNotBlank()) " — $occupationOther" else ""
        append("If occupied, response: ${occupationStance.label()}$occupationOtherPart")
    }
    is MandateForm.Military -> buildString {
        appendLine("Target land: ${targetLand.ifBlank { "-" }}")
        appendLine("Action: ${action?.name ?: "-"}")
        if (action == MilitaryAction.OCCUPY) {
            appendLine("New landowner: ${newLandowner.ifBlank { "-" }}")
        }
        val travelerExceptionsPart = if (stopTravelers == MandateYesNo.YES && travelerExceptions.isNotBlank()) " — except: $travelerExceptions" else ""
        append("Stop travelers: ${stopTravelers.label()}$travelerExceptionsPart")
    }
}

private fun MandateYesNo?.label(): String = when (this) {
    MandateYesNo.YES -> "Yes"
    MandateYesNo.NO -> "No"
    null -> "-"
}

private fun MandateYesNoOther?.label(): String = when (this) {
    MandateYesNoOther.YES -> "Yes"
    MandateYesNoOther.NO -> "No"
    MandateYesNoOther.OTHER -> "Other"
    null -> "-"
}

private fun MandateHelpHinderOther?.label(): String = when (this) {
    MandateHelpHinderOther.HELP -> "Help"
    MandateHelpHinderOther.HINDER -> "Hinder"
    MandateHelpHinderOther.OTHER -> "Other"
    null -> "-"
}
