package com.coding.va.selfhelp.domain.model

import kotlinx.serialization.Serializable

@Serializable
enum class MandateYesNo { YES, NO }

@Serializable
enum class MandateYesNoOther { YES, NO, OTHER }

@Serializable
enum class MandateHelpHinderOther { HELP, HINDER, OTHER }

@Serializable
enum class MilitaryAction { DEFEND, SPY, RAID, OCCUPY }

@Serializable
sealed class MandateForm {
    abstract val ocName: String
    /** PLIN composite — first = PLIN digits, second = CHIN digits. */
    abstract val plin: Pair<String, String>
    abstract val characterName: String

    @Serializable
    data class Land(
        override val ocName: String = "",
        override val plin: Pair<String, String> = Pair("", ""),
        override val characterName: String = "",
        val landName: String = "",
        val taxationPer100: String = "",
        val spendFirstOn: String = "",
        val spendLeftoverOn: String = "",
        val disband: String = "",
        val specialInstructions: String = "",
    ) : MandateForm()

    @Serializable
    data class People(
        override val ocName: String = "",
        override val plin: Pair<String, String> = Pair("", ""),
        override val characterName: String = "",
        val peopleName: String = "",
        val migrate: MandateYesNo? = null,
        val migrateWhere: String = "",
        val militia: MandateYesNoOther? = null,
        val militiaOther: String = "",
        val grow: MandateYesNoOther? = null,
        val growOther: String = "",
        val occupationStance: MandateHelpHinderOther? = null,
        val occupationOther: String = "",
        val otherAdvice: String = "",
    ) : MandateForm()

    @Serializable
    data class Military(
        override val ocName: String = "",
        override val plin: Pair<String, String> = Pair("", ""),
        override val characterName: String = "",
        val regimentName: String = "",
        val targetLand: String = "",
        val action: MilitaryAction? = null,
        val newLandowner: String = "",
        val stopTravelers: MandateYesNo? = null,
        val travelerExceptions: String = "",
        val specialInstructions: String = "",
    ) : MandateForm()
}
