@Composable
fun LandingContent(
    display: LandingScreenDisplay,
    onEvent: ((LandingScreenEvent) -> Unit)? = null
) {
    val isDesktop = getPlatform() == TYPE.DESKTOP
    val strings = LocalStrings.current

    display.errorBox?.let {
        ErrorBox(
            display = it,
            onConfirmation = { },
            onDismissRequest = { onEvent?.invoke(LandingScreenEvent.DismissError) })
    }

    Column(Modifier.fillMaxSize().background(paper)) {
        VortexTopBar(
            right = {
                TopBarPill(text = display.languageToggleLabel, onClick = { onEvent?.invoke(LandingScreenEvent.ToggleLanguage) })
                if (isDesktop) SettingsMenu(display, onEvent)
            },
        )

        KioskScrollColumn(
            modifier = Modifier
                .weight(1f)
                .fillMaxWidth(),
            contentPadding = PaddingValues(horizontal = 24.dp, vertical = 24.dp),
            horizontalAlignment = Alignment.CenterHorizontally,
        ) {
            Column(Modifier.widthIn(max = 860.dp).fillMaxWidth(), horizontalAlignment = Alignment.CenterHorizontally) {
                // hero — centered instruction; the crest + brand live in the top bar
                Text(
                    text = display.description,
                    style = TextStyle(fontFamily = BodyFamily(), fontSize = 17.sp),
                    color = ink2,
                    textAlign = TextAlign.Center,
                    modifier = Modifier.fillMaxWidth().padding(vertical = 8.dp).semantics { heading() },
                )

                display.serviceMessage?.let {
                    Spacer(Modifier.height(20.dp))
                    Banner(kind = BannerKind.Service, text = it)
                }

                // task tiles (2-up, trailing odd tile spans full width)
                Spacer(Modifier.height(24.dp))
                Column(verticalArrangement = Arrangement.spacedBy(12.dp), modifier = Modifier.fillMaxWidth()) {
                    display.tasks.chunked(2).forEach { chunk ->
                        if (chunk.size == 1) {
                            TaskTile(
                                text = chunk[0].title,
                                subtitle = chunk[0].subtitle,
                                onClick = { onEvent?.invoke(chunk[0].action) },
                                modifier = Modifier.fillMaxWidth(),
                                minHeight = if (isDesktop) 86.dp else 68.dp,
                            )
                        } else {
                            Row(
                                modifier = Modifier.fillMaxWidth().height(IntrinsicSize.Min),
                                horizontalArrangement = Arrangement.spacedBy(12.dp),
                            ) {
                                chunk.forEach { item ->
                                    TaskTile(
                                        text = item.title,
                                        subtitle = item.subtitle,
                                        onClick = { onEvent?.invoke(item.action) },
                                        modifier = Modifier.weight(1f).fillMaxHeight(),
                                        minHeight = if (isDesktop) 124.dp else 96.dp,
                                    )
                                }
                            }
                        }
                    }
                }

                // print a card
                display.printField?.let { printField ->
                    Spacer(Modifier.height(28.dp))
                    Box(Modifier.fillMaxWidth().height(1.dp).background(vellumLine))
                    Spacer(Modifier.height(20.dp))
                    Text(
                        text = strings.landing.printSectionTitle,
                        style = TextStyle(fontFamily = DisplayFamily(), fontWeight = FontWeight.SemiBold, fontSize = 20.sp),
                        color = ink,
                        modifier = Modifier.fillMaxWidth(),
                    )
                    Spacer(Modifier.height(8.dp))
                    display.printDescription?.let {
                        Text(text = it, style = TextStyle(fontFamily = BodyFamily(), fontSize = 14.sp), color = ink2, modifier = Modifier.fillMaxWidth())
                        Spacer(Modifier.height(12.dp))
                    }
                    // The hint renders below the row so the button lines up with the
                    // input box instead of the bottom of the wrapped helper text.
                    Row(
                        // Fill the section width so the row left-aligns with the texts
                        // around it (the parent column centers non-filling children).
                        modifier = Modifier.fillMaxWidth(),
                        verticalAlignment = Alignment.Bottom,
                        horizontalArrangement = Arrangement.spacedBy(12.dp),
                    ) {
                        VortexField(
                            fieldWidth = 220.dp,
                            label = printField.label,
                            value = display.cardCode,
                            mono = true,
                            onValueChange = { onEvent?.invoke(LandingScreenEvent.CardCode(it.uppercase())) },
                        )
                        display.attemptPrintButton?.let { btn ->
                            VortexButton(
                                text = btn.label,
                                onClick = { onEvent?.invoke(LandingScreenEvent.PrintCard) },
                                variant = VortexButtonVariant.Secondary,
                                enabled = !btn.loading,
                            )
                        }
                    }
                    FieldFooter(error = null, hint = printField.hint, expand = true, constrainWidth = null)
                }

                // account (mobile)
                display.loginButton?.let { label ->
                    Spacer(Modifier.height(24.dp))
                    VortexButton(
                        text = label,
                        onClick = { onEvent?.invoke(LandingScreenEvent.NavigateToLogin) },
                        variant = VortexButtonVariant.Ghost,
                        modifier = Modifier.fillMaxWidth(),
                    )
                }
                display.myCharacterButton?.let { label ->
                    Spacer(Modifier.height(8.dp))
                    VortexButton(
                        text = label,
                        onClick = { onEvent?.invoke(LandingScreenEvent.NavigateToCharacterDetail) },
                        variant = VortexButtonVariant.Ghost,
                        modifier = Modifier.fillMaxWidth(),
                    )
                }

                // feedback (mobile only — provided by display)
                if (display.feedbackButton != null && display.feedbackUrl != null) {
                    val uriHandler = LocalUriHandler.current
                    Spacer(Modifier.height(8.dp))
                    VortexButton(
                        text = display.feedbackButton,
                        onClick = { uriHandler.openUri(display.feedbackUrl) },
                        variant = VortexButtonVariant.Ghost,
                        modifier = Modifier.fillMaxWidth(),
                    )
                }
            }
        }
    }
}

/** Desktop kiosk settings — cog in the top bar opening the printer/sheet admin menu. */
@Composable
private fun SettingsMenu(display: LandingScreenDisplay, onEvent: ((LandingScreenEvent) -> Unit)?) {
    var menuExpanded by remember { mutableStateOf(false) }
    val a11y = LocalStrings.current.a11y
    Box {
        UnstyledDropdownMenu(onExpandRequest = { menuExpanded = true }) {
            TopBarPill(
                text = "⚙",
                onClick = { menuExpanded = !menuExpanded },
                modifier = Modifier.semantics { role = Role.Button; contentDescription = a11y.menuButton },
            )
            UnstyledDropdownMenuPanel(
                expanded = menuExpanded,
                onDismissRequest = { menuExpanded = false },
                modifier = Modifier.padding(vertical = 4.dp)
                    .width(280.dp)
                    .shadow(4.dp, RoundedCornerShape(10.dp))
                    .clip(RoundedCornerShape(10.dp))
                    .background(paperRaised),
                enter = scaleIn(
                    animationSpec = tween(durationMillis = 120, easing = LinearOutSlowInEasing),
                    initialScale = 0.8f,
                    transformOrigin = TransformOrigin(1f, 0f)
                ) + fadeIn(tween(durationMillis = 30)),
                exit = scaleOut(
                    animationSpec = tween(durationMillis = 1, delayMillis = 75),
                    targetScale = 1f
                ) + fadeOut(tween(durationMillis = 75))
            ) {
                Column(modifier = Modifier.verticalScroll(rememberScrollState()).padding(12.dp)) {
                    Text(
                        text = display.menuDisplay.header,
                        style = TextStyle(fontFamily = DisplayFamily(), fontWeight = FontWeight.SemiBold, fontSize = 18.sp),
                        color = ink,
                        modifier = Modifier.fillMaxWidth().padding(bottom = 12.dp),
                    )
                    when (val menu = display.menuDisplay) {
                        is MenuDisplay.Locked -> {
                            OutlinedTextField(
                                modifier = Modifier.padding(vertical = 4.dp),
                                isError = false,
                                value = menu.password,
                                visualTransformation = PasswordVisualTransformation(),
                                onValueChange = { onEvent?.invoke(LandingScreenEvent.MenuChange(menu.copy(password = it))) },
                                label = { Text(text = menu.passwordLabel) }
                            )
                        }

                        is MenuDisplay.UnLocked -> {
                            Row(verticalAlignment = Alignment.CenterVertically, modifier = Modifier.padding(vertical = 4.dp)) {
                                Text(text = menu.printerModeLabel)
                                Button(
                                    modifier = Modifier.padding(horizontal = 4.dp),
                                    onClick = {
                                        val newMode = if (menu.printerMode == "usb") "network" else "usb"
                                        onEvent?.invoke(LandingScreenEvent.MenuChange(menu.copy(printerMode = newMode)))
                                    }
                                ) {
                                    Text(text = if (menu.printerMode == "usb") menu.printerModeUsbLabel else menu.printerModeNetworkLabel)
                                }
                            }
                            if (menu.printerMode == "network") {
                                OutlinedTextField(
                                    modifier = Modifier.padding(vertical = 4.dp),
                                    isError = false,
                                    value = menu.printerIp,
                                    onValueChange = { onEvent?.invoke(LandingScreenEvent.MenuChange(menu.copy(printerIp = it))) },
                                    label = { Text(text = menu.printerIpLabel) }
                                )
                            }
                            Row(verticalAlignment = Alignment.CenterVertically, modifier = Modifier.padding(vertical = 4.dp)) {
                                Checkbox(
                                    checked = menu.printerEnabled,
                                    onCheckedChange = { onEvent?.invoke(LandingScreenEvent.MenuChange(menu.copy(printerEnabled = it))) },
                                )
                                Text(text = menu.printerEnabledLabel)
                            }
                            Row(verticalAlignment = Alignment.CenterVertically, modifier = Modifier.padding(vertical = 4.dp)) {
                                Checkbox(
                                    checked = menu.printerCodeEnabled,
                                    onCheckedChange = { onEvent?.invoke(LandingScreenEvent.MenuChange(menu.copy(printerCodeEnabled = it))) },
                                )
                                Text(text = menu.printerCodeEnabledLabel)
                            }
                            OutlinedTextField(
                                modifier = Modifier.padding(vertical = 4.dp),
                                isError = false,
                                value = menu.deviceIp,
                                enabled = false,
                                onValueChange = {},
                                label = { Text(text = menu.deviceIpLabel) }
                            )
                            VortexButton(
                                text = menu.save,
                                onClick = { onEvent?.invoke(LandingScreenEvent.MenuSave) },
                                modifier = Modifier.fillMaxWidth().padding(top = 8.dp),
                            )
                            VortexButton(
                                text = menu.lock,
                                onClick = { onEvent?.invoke(LandingScreenEvent.MenuLock) },
                                variant = VortexButtonVariant.Ghost,
                                modifier = Modifier.fillMaxWidth().padding(top = 8.dp),
                            )
                        }
                    }
                }
            }
        }
    }
}
