package com.coding.va.selfhelp.presentation.screens.model

import com.coding.va.selfhelp.domain.model.EntryType

typealias VortexItemCardDisplay = com.coding.va.selfhelp.domain.model.VortexItemCardDisplay

fun VortexItemCardDisplay.getEasyName(type: EntryType): String? {
    return when (type) {
        EntryType.CRAFT_ITEM -> itemName
        EntryType.IMBUE_ITEM -> "$targetItin - $power"
        EntryType.RECHARGE_ITEM -> targetItin
        EntryType.IMBUE_PERSON -> "$targetPlin - $power"
        EntryType.MUNDANE_ITEM -> itemName
        EntryType.LAND_MANDATE,
        EntryType.PEOPLE_MANDATE,
        EntryType.MILITARY_ORDERS -> null
    }
}
