package com.coding.va.selfhelp.domain.use_cases

import com.coding.va.selfhelp.domain.exceptions.AccountNotLinkedException
import com.coding.va.selfhelp.domain.respository.AuthRepository
import org.koin.core.annotation.Factory

/**
 * Exchanges a Keycloak PKCE authorization code for an access/refresh token pair and
 * persists the tokens. This is the final step of the browser-based OAuth flow.
 */
@Factory
class ExchangeEruCodeUseCase(private val repository: AuthRepository) {

    /**
     * @param code          The authorization code received in the OAuth callback.
     * @param redirectUri   The exact redirect URI used when launching the auth URL (must match).
     * @param codeVerifier  The PKCE code verifier generated before launching the browser.
     *
     * Fails with [AccountNotLinkedException] when authentication succeeded but the
     * ERU profile carries no PLIN — the account exists and nobody has linked it to
     * a player yet. Without this check the login "succeeds", CharacterSelect then
     * cannot resolve a PLIN, and the player sees a generic error instead of the
     * explanation that a game master still has to link their account.
     */
    suspend operator fun invoke(
        code: String,
        redirectUri: String,
        codeVerifier: String?,
    ): Result<Unit> =
        repository.exchangeCodeForTokens(code, redirectUri, codeVerifier)
            .mapCatching { (access, refresh) ->
                repository.storeTokens(access, refresh)
                // Tokens are kept deliberately: they are valid, and re-checking after
                // a game master links the account needs no second sign-in.
                val plin = repository.getPlin().getOrElse { cause ->
                    throw cause
                }
                if (plin == null) {
                    throw AccountNotLinkedException()
                }
            }
}
