package com.coding.va.selfhelp.presentation.screens.login

import com.coding.va.selfhelp.i18n.AppStrings
import com.coding.va.selfhelp.presentation.screens.login.model.LoginScreenDisplay

object LoginDisplayProvider {

    fun loading() = LoginScreenDisplay.Loading

    fun authenticating(strings: AppStrings) = LoginScreenDisplay.Display(
        title = strings.login.sectionTitle,
        statusLabel = strings.login.loggingInLabel,
        isAuthenticating = true,
        backButton = strings.login.backButton,
    )

    fun cancelled(strings: AppStrings) = LoginScreenDisplay.Display(
        title = strings.login.sectionTitle,
        statusLabel = strings.login.signInPrompt,
        isAuthenticating = false,
        backButton = strings.login.backButton,
    )

    fun unlinkedAccount(strings: AppStrings) = LoginScreenDisplay.Error(
        title = strings.login.loginUnlinkedTitle,
        description = strings.login.loginUnlinkedDescription,
        retryButton = strings.login.backButton,
        backButton = strings.login.backButton,
    )

    fun error(strings: AppStrings) = LoginScreenDisplay.Error(
        title = strings.login.loginErrorTitle,
        description = strings.login.loginErrorDescription,
        retryButton = strings.login.loginErrorButton,
        backButton = strings.login.backButton,
    )
}